INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (30,54,'Ar-Room','۞ٱللَّهُ ٱلَّذِي خَلَقَكُم مِّن ضَعۡفࣲ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفࣲ قُوَّةࣰ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةࣲ ضَعۡفࣰ ا وَشَيۡبَةࣰۚ يَخۡلُقُ مَا يَشَآءُۚ وَهُوَ ٱلۡعَلِيمُ ٱلۡقَدِيرُ','خدا ہی تو ہے جس نے تم کو (ابتدا میں) کمزور حالت میں پیدا کیا پھر کمزوری کے بعد طاقت عنایت کی پھر طاقت کے بعد کمزوری اور بڑھاپا دیا۔ وہ جو چاہتا ہے پیدا کرتا ہے اور وہ صاحب دانش اور صاحب قدرت ہے','It is Allah Who created you in a state of weakness, then developed ˹your˺ weakness into strength, then developed ˹your˺ strength into weakness and old age. He creates whatever He wills. For He is the All-Knowing, Most Capable','खुदा ही तो है जिसने तुम्हें (एक निहायत) कमज़ोर चीज़ (नुत्फे) से पैदा किया फिर उसी ने (तुम में) बचपने की कमज़ोरी के बाद (शबाब की) क़ूवत अता की फिर उसी ने (तुममें जवानी की) क़ूवत के बाद कमज़ोरी और बुढ़ापा पैदा कर दिया वह जो चाहता पैदा करता है-और वही बड़ा वाकिफकार और (हर चीज़ पर) क़ाबू रखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (30,55,'Ar-Room','وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ يُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُواْ غَيۡرَ سَاعَةࣲۚ كَذَٰلِكَ كَانُواْ يُؤۡفَكُونَ','اور جس روز قیامت برپا ہوگی گنہگار قسمیں کھائیں گے کہ وہ (دنیا میں) ایک گھڑی سے زیادہ نہیں رہے تھے۔ اسی طرح وہ (رستے سے) اُلٹے جاتے تھے','And on the Day the Hour will arrive, the wicked will swear that they did not stay ˹in this world˺ more than an hour. In this way they were always deluded ˹in the world˺','और जिस दिन क़यामत बरपा होगी तो गुनाहगार लोग कसमें खाएँगें कि वह (दुनिया में) घड़ी भर से ज्यादा नहीं ठहरे यूँ ही लोग (दुनिया में भी) इफ़तेरा परदाज़ियाँ करते रहे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (30,56,'Ar-Room','وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَٱلۡإِيمَٰنَ لَقَدۡ لَبِثۡتُمۡ فِي كِتَٰبِ ٱللَّهِ إِلَىٰ يَوۡمِ ٱلۡبَعۡثِۖ فَهَٰذَا يَوۡمُ ٱلۡبَعۡثِ وَلَٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ','اور جن لوگوں کو علم اور ایمان دیا گیا تھا وہ کہیں گے کہ خدا کی کتاب کے مطابق تم قیامت تک رہے ہو۔ اور یہ قیامت ہی کا دن ہے لیکن تم کو اس کا یقین ہی نہیں تھا','But those gifted with knowledge and faith will say ˹to them˺, “You did actually stay—as destined by Allah—until the Day of Resurrection. So here is the Day of Resurrection ˹which you denied˺! But you did not know ˹it was true˺.”','और जिन लोगों को (ख़ुदा की बारगाह से) इल्म और ईमान दिया गया है जवाब देगें कि (हाए) तुम तो ख़ुदा की किताब के मुताबिक़ रोज़े क़यामत तक (बराबर) ठहरे रहे फिर ये तो क़यामत का ही दिन है मगर तुम लोग तो उसका यक़ीन ही न रखते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (30,57,'Ar-Room','فَيَوۡمَئِذࣲ لَّا يَنفَعُ ٱلَّذِينَ ظَلَمُواْ مَعۡذِرَتُهُمۡ وَلَا هُمۡ يُسۡتَعۡتَبُونَ','تو اس روز ظالم لوگوں کو ان کا عذر کچھ فائدہ نہ دے گا اور نہ اُن سے توبہ قبول کی جائے گی','So on that Day the wrongdoers’ excuses will not benefit them, nor will they be allowed to appease ˹their Lord˺','तो उस दिन सरकश लोगों को न उनकी उज्र माअज़ेरत कुछ काम आएगी और न उनकी सुनवाई होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (30,58,'Ar-Room','وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲۚ وَلَئِن جِئۡتَهُم بِـَٔايَةࣲ لَّيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ أَنتُمۡ إِلَّا مُبۡطِلُونَ','اور ہم نے لوگوں کے (سمجھانے کے) لئے اس قرآن میں ہر طرح کی مثال بیان کر دی ہے اور اگر تم اُن کے سامنے کوئی نشانی پیش کرو تو یہ کافر کہہ دیں گے کہ تم تو جھوٹے ہو','We have certainly set forth every ˹kind of˺ lesson for people in this Quran. And no matter what sign you bring to them ˹O Prophet˺, the disbelievers will definitely say ˹to the believers˺, “You are only a people of falsehood.”','और हमने तो इस कुरान में (लोगों के समझाने को) हर तरह की मिसल बयान कर दी और अगर तुम उनके पास कोई सा मौजिज़ा ले आओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (30,59,'Ar-Room','كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِينَ لَا يَعۡلَمُونَ','اسی طرح خدا اُن لوگوں کے دلوں پر جو سمجھ نہیں رکھتے مہر لگا دیتا ہے','This is how Allah seals the hearts of those unwilling to know ˹the truth˺','तो भी यक़ीनन कुफ्फ़ार यही बोल उठेंगे कि तुम लोग निरे दग़ाबाज़ हो जो लोग समझ (और इल्म) नहीं रखते उनके दिलों पर नज़र करके ख़ुदा यू तसदीक़ करता है (कि ये ईमान न लाएँगें)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (30,60,'Ar-Room','فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ وَلَا يَسۡتَخِفَّنَّكَ ٱلَّذِينَ لَا يُوقِنُونَ','پس تم صبر کرو بیشک خدا کا وعدہ سچا ہے اور (دیکھو) جو لوگ یقین نہیں رکھتے وہ تمہیں اوچھا نہ بنادیں','So be patient, for the promise of Allah certainly is true. And do not be disturbed by those who have no sure faith','तो (ऐ रसूल) तुम सब्र करो बेशक ख़ुदा का वायदा सच्चा है और (कहीं) ऐसा न हो कि जो (तुम्हारी) तसदीक़ नहीं करते तुम्हें (बहका कर) ख़फ़ीफ़ करे दें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,1,'Luqman','الٓمٓ','الٓمٓ','Alif-Lãm-Mĩm','अलिफ़ लाम मीम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,2,'Luqman','تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡحَكِيمِ','یہ حکمت کی (بھری ہوئی) کتاب کی آیتیں ہیں','These are the verses of the Book, rich in wisdom','ये सूरा हिकमत से भरी हुई किताब की आयतें है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,3,'Luqman','هُدࣰ ى وَرَحۡمَةࣰ لِّلۡمُحۡسِنِينَ','نیکوکاروں کے لئے ہدایت اور رحمت ہے','˹It is˺ a guide and mercy for the good-doers—','जो (अज़सरतापा) उन लोगों के लिए हिदायत व रहमत है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,4,'Luqman','ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ','جو نماز کی پابندی کرتے اور زکوٰة دیتے اور آخرت کا یقین رکھتے ہیں','those who establish prayer, pay alms-tax, and have sure faith in the Hereafter','जो पाबन्दी से नमाज़ अदा करते हैं और ज़कात देते हैं और वही लोग आख़िरत का भी यक़ीन रखते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,5,'Luqman','أُوْلَٰٓئِكَ عَلَىٰ هُدࣰ ى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ','یہی اپنے پروردگار (کی طرف) سے ہدایت پر ہیں اور یہی نجات پانے والے ہیں','It is they who are ˹truly˺ guided by their Lord, and it is they who will be successful','यही लोग अपने परवरदिगार की हिदायत पर आमिल हैं और यही लोग (क़यामत में) अपनी दिली मुरादें पाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,6,'Luqman','وَمِنَ ٱلنَّاسِ مَن يَشۡتَرِي لَهۡوَ ٱلۡحَدِيثِ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِ بِغَيۡرِ عِلۡمࣲ وَيَتَّخِذَهَا هُزُوًاۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابࣱ مُّهِينࣱ‏','اور لوگوں میں بعض ایسا ہے جو بیہودہ حکایتیں خریدتا ہے تاکہ (لوگوں کو) بےسمجھے خدا کے رستے سے گمراہ کرے اور اس سے استہزاء کرے یہی لوگ ہیں جن کو ذلیل کرنے والا عذاب ہوگا','But there are some who employ theatrics, only to lead others away from Allah’s Way—without any knowledge—and to make a mockery of it. They will suffer a humiliating punishment','और लोगों में बाज़ (नज़र बिन हारिस) ऐसा है जो बेहूदा क़िस्से (कहानियाँ) ख़रीदता है ताकि बग़ैर समझे बूझे (लोगों को) ख़ुदा की (सीधी) राह से भड़का दे और आयातें ख़ुदा से मसख़रापन करे ऐसे ही लोगों के लिए बड़ा रुसवा करने वाला अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,7,'Luqman','وَإِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا وَلَّىٰ مُسۡتَكۡبِرࣰ ا كَأَن لَّمۡ يَسۡمَعۡهَا كَأَنَّ فِيٓ أُذُنَيۡهِ وَقۡرࣰ اۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِيمٍ','اور جب اس کو ہماری آیتیں سنائی جاتی ہیں تو اکڑ کر منہ پھیر لیتا ہے گویا اُن کو سنا ہی نہیں جیسے اُن کے کانوں میں ثقل ہے تو اس کو درد دینے والے عذاب کی خوشخبری سنادو','Whenever Our revelations are recited to them, they turn away in arrogance as if they did not hear them, as if there is deafness in their ears. So give them good news ˹O Prophet˺ of a painful punishment','और जब उसके सामने हमारी आयतें पढ़ी जाती हैं तो शेख़ी के मारे मुँह फेरकर (इस तरह) चल देता है गोया उसने इन आयतों को सुना ही नहीं जैसे उसके दोनो कानों में ठेठी है तो (ऐ रसूल) तुम उसको दर्दनाक अज़ाब की (अभी से) खुशख़बरी दे दे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,8,'Luqman','إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُمۡ جَنَّٰتُ ٱلنَّعِيمِ','جو لوگ ایمان لائے اور نیک کام کرتے رہے اُن کے لئے نعمت کے باغ ہیں','Surely those who believe and do good will have the Gardens of Bliss','बेशक जो लोग ईमान लाए और उन्होंने अच्छे काम किए उनके लिए नेअमत के (हरे भरे बेहश्ती) बाग़ हैं कि यो उनमें हमेशा रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,9,'Luqman','خَٰلِدِينَ فِيهَاۖ وَعۡدَ ٱللَّهِ حَقࣰّ اۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ','ہمیشہ اُن میں رہیں گے۔ خدا کا وعدہ سچا ہے اور وہ غالب حکمت والا ہے','staying there forever. Allah’s promise is true. And He is the Almighty, All-Wise','ये ख़ुदा का पक्का वायदा है और वह तो (सब पर) ग़ालिब हिकमत वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,10,'Luqman','خَلَقَ ٱلسَّمَٰوَٰتِ بِغَيۡرِ عَمَدࣲ تَرَوۡنَهَاۖ وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةࣲۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجࣲ كَرِيمٍ','اُسی نے آسمانوں کو ستونوں کے بغیر پیدا کیا جیسا کہ تم دیکھتے ہو اور زمین پر پہاڑ (بنا کر) رکھ دیئے تاکہ تم کو ہلا ہلا نہ دے اور اس میں ہر طرح کے جانور پھیلا دیئے۔ اور ہم ہی نے آسمانوں سے پانی نازل کیا پھر (اُس سے) اس میں ہر قسم کی نفیس چیزیں اُگائیں','He created the heavens without pillars—as you can see—and placed firm mountains upon the earth so it does not shake with you, and scattered throughout it all types of creatures. And We send down rain from the sky, causing every type of fine plant to grow on earth','तुम उन्हें देख रहे हो कि उसी ने बग़ैर सुतून के आसमानों को बना डाला और उसी ने ज़मीन पर (भारी भारी) पहाड़ों के लंगर डाल दिए कि (मुबादा) तुम्हें लेकर किसी तरफ जुम्बिश करे और उसी ने हर तरह चल फिर करने वाले (जानवर) ज़मीन में फैलाए और हमने आसमान से पानी बरसाया और (उसके ज़रिए से) ज़मीन में हर रंग के नफ़ीस जोड़े पैदा किए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,11,'Luqman','هَٰذَا خَلۡقُ ٱللَّهِ فَأَرُونِي مَاذَا خَلَقَ ٱلَّذِينَ مِن دُونِهِۦۚ بَلِ ٱلظَّٰلِمُونَ فِي ضَلَٰلࣲ مُّبِينࣲ‏','یہ تو خدا کی پیدائش ہے تو مجھے دکھاؤ کہ خدا کے سوا جو لوگ ہیں اُنہوں نے کیا پیدا کیا ہے؟ حقیقت یہ ہے کہ یہ ظالم صریح گمراہی میں ہیں','This is Allah’s creation. Now show Me what those ˹gods˺ other than Him have created. In fact, the wrongdoers are clearly astray','(ऐ रसूल उनसे कह दो कि) ये तो खुदा की ख़िलक़त है कि (भला) तुम लोग मुझे दिखाओं तो कि जो (जो माबूद) ख़ुदा के सिवा तुमने बना रखे है उन्होंने क्या पैदा किया बल्कि सरकश लोग (कुफ्फ़ार) सरीही गुमराही में (पडे) हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,12,'Luqman','وَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدࣱ‏','اور ہم نے لقمان کو دانائی بخشی۔ کہ خدا کا شکر کرو۔ اور جو شخص شکر کرتا ہے تو اپنے ہی فائدے کے لئے شکر کرتا ہے۔ اور جو ناشکری کرتا ہے تو خدا بھی بےپروا اور سزاوار حمد (وثنا) ہے','Indeed, We blessed Luqmân with wisdom, ˹saying˺, “Be grateful to Allah, for whoever is grateful, it is only for their own good. And whoever is ungrateful, then surely Allah is Self-Sufficient, Praiseworthy.”','और यक़ीनन हम ने लुक़मान को हिकमत अता की (और हुक्म दिया था कि) तुम ख़ुदा का शुक्र करो और जो ख़ुदा का शुक्र करेगा-वह अपने ही फायदे के लिए शुक्र करता है और जिसने नाशुक्री की तो (अपना बिगाड़ा) क्योंकी ख़ुदा तो (बहरहाल) बे परवाह (और) क़ाबिल हमदो सना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,13,'Luqman','وَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمࣱ‏','اور (اُس وقت کو یاد کرو) جب لقمان نے اپنے بیٹے کو نصیحت کرتے ہوئے کہا کہ بیٹا خدا کے ساتھ شرک نہ کرنا۔ شرک تو بڑا (بھاری) ظلم ہے','And ˹remember˺ when Luqmân said to his son, while advising him, “O my dear son! Never associate ˹anything˺ with Allah ˹in worship˺, for associating ˹others with Him˺ is truly the worst of all wrongs.”','और (वह वक्त याद करो) जब लुक़मान ने अपने बेटे से उसकी नसीहत करते हुए कहा ऐ बेटा (ख़बरदार कभी किसी को) ख़ुदा का शरीक न बनाना (क्योंकि) शिर्क यक़ीनी बड़ा सख्त गुनाह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,14,'Luqman','وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنࣲ وَفِصَٰلُهُۥ فِي عَامَيۡنِ أَنِ ٱشۡكُرۡ لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ','اور ہم نے انسان کو جسے اُس کی ماں تکلیف پر تکلیف سہہ کر پیٹ میں اُٹھائے رکھتی ہے (پھر اس کو دودھ پلاتی ہے) اور (آخرکار) دو برس میں اس کا دودھ چھڑانا ہوتا ہے (اپنے نیز) اس کے ماں باپ کے بارے میں تاکید کی ہے کہ میرا بھی شکر کرتا رہ اور اپنے ماں باپ کا بھی (کہ تم کو) میری ہی طرف لوٹ کر آنا ہے','And We have commanded people to ˹honour˺ their parents. Their mothers bore them through hardship upon hardship, and their weaning takes two years. So be grateful to Me and your parents. To Me is the final return','(जिस की बख़्शिस नहीं) और हमने इन्सान को जिसे उसकी माँ ने दुख पर दुख सह के पेट में रखा (इसके अलावा) दो बरस में (जाके) उसकी दूध बढ़ाई की (अपने और) उसके माँ बाप के बारे में ताक़ीद की कि मेरा भी शुक्रिया अदा करो और अपने वालदैन का (भी) और आख़िर सबको मेरी तरफ लौट कर जाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,15,'Luqman','وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمࣱ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِي ٱلدُّنۡيَا مَعۡرُوفࣰ اۖ وَٱتَّبِعۡ سَبِيلَ مَنۡ أَنَابَ إِلَيَّۚ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ','اور اگر وہ تیرے درپے ہوں کہ تو میرے ساتھ کسی ایسی چیز کو شریک کرے جس کا تجھے کچھ بھی علم نہیں تو ان کا کہا نہ ماننا۔ ہاں دنیا (کے کاموں) میں ان کا اچھی طرح ساتھ دینا اور جو شخص میری طرف رجوع لائے اس کے رستے پر چلنا پھر تم کو میری طرف لوٹ کر آنا ہے۔ تو جو کام تم کرتے رہے میں سب سے تم کو آگاہ کروں گا','But if they pressure you to associate with Me what you have no knowledge of, do not obey them. Still keep their company in this world courteously, and follow the way of those who turn to Me ˹in devotion˺. Then to Me you will ˹all˺ return, and then I will inform you of what you used to do','और अगर तेरे माँ बाप तुझे इस बात पर मजबूर करें कि तू मेरा शरीक ऐसी चीज़ को क़रार दे जिसका तुझे इल्म भी नहीं तो तू (इसमें) उनकी इताअत न करो (मगर तकलीफ़ न पहुँचाना) और दुनिया (के कामों) में उनका अच्छी तरह साथ दे और उन लोगों के तरीक़े पर चल जो (हर बात में) मेरी (ही) तरफ रुजू करे फिर (तो आख़िर) तुम सबकी रुजू मेरी ही तरफ है तब (दुनिया में) जो कुछ तुम करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,16,'Luqman','يَٰبُنَيَّ إِنَّهَآ إِن تَكُ مِثۡقَالَ حَبَّةࣲ مِّنۡ خَرۡدَلࣲ فَتَكُن فِي صَخۡرَةٍ أَوۡ فِي ٱلسَّمَٰوَٰتِ أَوۡ فِي ٱلۡأَرۡضِ يَأۡتِ بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرࣱ‏','(لقمان نے یہ بھی کہا کہ) بیٹا اگر کوئی عمل (بالفرض) رائی کے دانے کے برابر بھی (چھوٹا) ہو اور ہو بھی کسی پتھر کے اندر یا آسمانوں میں (مخفی ہو) یا زمین میں۔ خدا اُس کو قیامت کے دن لاموجود کرے گا۔ کچھ شک نہیں کہ خدا باریک بین (اور) خبردار ہے','˹Luqmân added,˺ “O my dear son! ˹Even˺ if a deed were the weight of a mustard seed—be it ˹hidden˺ in a rock or in the heavens or the earth—Allah will bring it forth. Surely Allah is Most Subtle, All-Aware','(उस वक्त उसका अन्जाम) बता दूँगा ऐ बेटा इसमें शक नहीं कि वह अमल (अच्छा हो या बुरा) अगर राई के बराबर भी हो और फिर वह किसी सख्त पत्थर के अन्दर या आसमान में या ज़मीन मे (छुपा हुआ) हो तो भी ख़ुदा उसे (क़यामत के दिन) हाज़िर कर देगा बेशक ख़ुदा बड़ा बारीकबीन वाक़िफकार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,17,'Luqman','يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ','بیٹا نماز کی پابندی رکھنا اور (لوگوں کو) اچھے کاموں کے کرنے کا امر اور بری باتوں سے منع کرتے رہنا اور جو مصیبت تجھ پر واقع ہو اس پر صبر کرنا۔ بیشک یہ بڑی ہمت کے کام ہیں','“O my dear son! Establish prayer, encourage what is good and forbid what is evil, and endure patiently whatever befalls you. Surely this is a resolve to aspire to','ऐ बेटा नमाज़ पाबन्दी से पढ़ा कर और (लोगों से) अच्छा काम करने को कहो और बुरे काम से रोको और जो मुसीबत तुम पर पडे उस पर सब्र करो (क्योंकि) बेशक ये बड़ी हिम्मत का काम है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,18,'Luqman','وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورࣲ‏','اور (ازراہ غرور) لوگوں سے گال نہ پھلانا اور زمین میں اکڑ کر نہ چلنا۔ کہ خدا کسی اترانے والے خود پسند کو پسند نہیں کرتا','“And do not turn your nose up to people, nor walk pridefully upon the earth. Surely Allah does not like whoever is arrogant, boastful','और लोगों के सामने (गुरुर से) अपना मुँह न फुलाना और ज़मीन पर अकड़कर न चलना क्योंकि ख़ुदा किसी अकड़ने वाले और इतराने वाले को दोस्त नहीं रखता और अपनी चाल ढाल में मियाना रवी एख्तेयार करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,19,'Luqman','وَٱقۡصِدۡ فِي مَشۡيِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ','اور اپنی چال میں اعتدال کئے رہنا اور (بولتے وقت) آواز نیچی رکھنا کیونکہ (اُونچی آواز گدھوں کی ہے اور کچھ شک نہیں کہ) سب آوازوں سے بُری آواز گدھوں کی ہے','Be moderate in your pace. And lower your voice, for the ugliest of all voices is certainly the braying of donkeys.”','और दूसरो से बोलने में अपनी आवाज़ धीमी रखो क्योंकि आवाज़ों में तो सब से बुरी आवाज़ (चीख़ने की वजह से) गधों की है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,20,'Luqman','أَلَمۡ تَرَوۡاْ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ وَأَسۡبَغَ عَلَيۡكُمۡ نِعَمَهُۥ ظَٰهِرَةࣰ وَبَاطِنَةࣰۗ وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمࣲ وَلَا هُدࣰ ى وَلَا كِتَٰبࣲ مُّنِيرࣲ‏','کیا تم نے نہیں دیکھا کہ جو کچھ آسمانوں میں اور جو کچھ زمین میں ہے سب کو خدا نے تمہارے قابو میں کر دیا ہے اور تم پر اپنی ظاہری اور باطنی نعمتیں پوری کردی ہیں۔ اور بعض لوگ ایسے ہیں کہ خدا کے بارے میں جھگڑتے ہیں نہ علم رکھتے ہیں اور نہ ہدایت اور نہ کتاب روشن','Have you not seen that Allah has subjected for you whatever is in the heavens and whatever is on the earth, and has lavished His favours upon you, both seen and unseen? ˹Still˺ there are some who dispute about Allah without knowledge, or guidance, or an enlightening scripture','क्या तुम लोगों ने इस पर ग़ौर नहीं किया कि जो कुछ आसमानों में है और जो कुछ ज़मीन में है (ग़रज़ सब कुछ) ख़ुदा ही ने यक़ीनी तुम्हारा ताबेए कर दिया है और तुम पर अपनी ज़ाहिरी और बातिनी नेअमतें पूरी कर दीं और बाज़ लोग (नुसर बिन हारिस वगैरह) ऐसे भी हैं जो (ख्वाह मा ख्वाह) ख़ुदा के बारे में झगड़ते हैं (हालॉकि उनके पास) न इल्म है और न हिदायत है और न कोई रौशन किताब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,21,'Luqman','وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ٱلشَّيۡطَٰنُ يَدۡعُوهُمۡ إِلَىٰ عَذَابِ ٱلسَّعِيرِ','اور جب اُن سے کہا جاتا ہے کہ جو (کتاب) خدا نے نازل فرمائی ہے اُس کی پیروی کرو۔ تو کہتے ہیں کہ ہم تو اسی کی پیروی کریں گے جس پر اپنے باپ دادا کو پایا۔ بھلا اگرچہ شیطان ان کو دوزخ کے عذاب کی طرف بلاتا ہو (تب بھی؟)','When it is said to them, “Follow what Allah has revealed,” they reply, “No! We ˹only˺ follow what we found our forefathers practicing.” ˹Would they still do so˺ even if Satan is inviting them to the torment of the Blaze','और जब उनसे कहा जाता है कि जो (किताब) ख़ुदा ने नाज़िल की है उसकी पैरवी करो तो (छूटते ही) कहते हैं कि नहीं हम तो उसी (तरीक़े से चलेंगे) जिस पर हमने अपने बाप दादाओं को पाया भला अगरचे शैतान उनके बाप दादाओं को जहन्नुम के अज़ाब की तरफ बुलाता रहा हो (तो भी उन्ही की पैरवी करेंगे)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,22,'Luqman','۞وَمَن يُسۡلِمۡ وَجۡهَهُۥٓ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنࣱ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَٰقِبَةُ ٱلۡأُمُورِ','اور جو شخص اپنے تئیں خدا کا فرمانبردار کردے اور نیکوکار بھی ہو تو اُس نے مضبوط دستاویز ہاتھ میں لے لی۔ اور (سب) کاموں کا انجام خدا ہی کی طرف ہے','Whoever fully submits themselves to Allah and is a good-doer, they have certainly grasped the firmest hand-hold. And with Allah rests the outcome of ˹all˺ affairs','और जो शख्स ख़ुदा के आगे अपना सर (तस्लीम) ख़म करे और वह नेकोकार (भी) हो तो बेशक उसने (ईमान की) मज़बूत रस्सी पकड़ ली और (आख़िर तो) सब कामों का अन्जाम ख़ुदा ही की तरफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,23,'Luqman','وَمَن كَفَرَ فَلَا يَحۡزُنكَ كُفۡرُهُۥٓۚ إِلَيۡنَا مَرۡجِعُهُمۡ فَنُنَبِّئُهُم بِمَا عَمِلُوٓاْۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ','اور جو کفر کرے تو اُس کا کفر تمہیں غمناک نہ کردے ان کو ہماری طرف لوٹ کر آنا ہے پھر جو کام وہ کیا کرتے تھے ہم اُن کو جتا ئیں گے۔ بیشک خدا دلوں کی باتوں سے واقف ہے','But whoever disbelieves, do not let their disbelief grieve you ˹O Prophet˺. To Us is their return, and We will inform them of all they did. Surely Allah knows best what is ˹hidden˺ in the heart','और (ऐ रसूल) जो काफिर बन बैठे तो तुम उसके कुफ्र से कुढ़ों नही उन सबको तो हमारी तरफ लौट कर आना है तो जो कुछ उन लोगों ने किया है (उसका नतीजा) हम बता देगें बेशक ख़ुदा दिलों के राज़ से (भी) खूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,24,'Luqman','نُمَتِّعُهُمۡ قَلِيلࣰ ا ثُمَّ نَضۡطَرُّهُمۡ إِلَىٰ عَذَابٍ غَلِيظࣲ‏','ہم اُن کو تھوڑا سا فائدہ پہنچائیں گے پھر عذاب شدید کی طرف مجبور کر کے لیجائیں گے','We allow them enjoyment for a little while, then ˹in time˺ We will force them into a harsh torment','हम उन्हें चन्द रोज़ों तक चैन करने देगें फिर उन्हें मजबूर करके सख्त अज़ाब की तरफ खीच लाएँगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,25,'Luqman','وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ','اور اگر تم اُن سے پوچھو کہ آسمانوں اور زمین کو کس نے پیدا کیا تو بول اُٹھیں گے کہ خدا نے۔ کہہ دو کہ خدا کا شکر ہے لیکن ان میں اکثر سمجھ نہیں رکھتے','And if you ask them who created the heavens and the earth, they will definitely say, “Allah!” Say, “Praise be to Allah!” In fact, most of them do not know','और (ऐ रसूल) तुम अगर उनसे पूछो कि सारे आसमान और ज़मीन को किसने पैदा किया तो ज़रुर कह देगे कि अल्लाह ने (ऐ रसूल) इस पर तुम कह दो अल्हमदोलिल्लाह मगर उनमें से अक्सर (इतना भी) नहीं जानते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,26,'Luqman','لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ','جو کچھ آسمانوں اور زمین میں ہے (سب) خدا ہی کا ہے۔ بیشک خدا بےپروا اور سزا وارِ حمد (وثنا) ہے','To Allah belongs whatever is in the heavens and the earth. Allah is truly the Self-Sufficient, Praiseworthy','जो कुछ सारे आसमान और ज़मीन में है (सब) ख़ुदा ही का है बेशक ख़ुदा तो (हर चीज़ से) बेपरवा (और बहरहाल) क़ाबिले हम्दो सना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,27,'Luqman','وَلَوۡ أَنَّمَا فِي ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَٰمࣱ وَٱلۡبَحۡرُ يَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرࣲ مَّا نَفِدَتۡ كَلِمَٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمࣱ‏','اور اگر یوں ہو کہ زمین میں جتنے درخت ہیں (سب کے سب) قلم ہوں اور سمندر (کا تمام پانی) سیاہی ہو (اور) اس کے بعد سات سمندر اور (سیاہی ہو جائیں) تو خدا کی باتیں (یعنی اس کی صفتیں) ختم نہ ہوں۔ بیشک خدا غالب حکمت والا ہے','If all the trees on earth were pens and the ocean ˹were ink˺, refilled by seven other oceans, the Words of Allah would not be exhausted. Surely Allah is Almighty, All-Wise','और जितने दरख्त ज़मीन में हैं सब के सब क़लम बन जाएँ और समन्दर उसकी सियाही बनें और उसके (ख़त्म होने के) बाद और सात समन्दर (सियाही हो जाएँ और ख़ुदा का इल्म और उसकी बातें लिखी जाएँ) तो भी ख़ुदा की बातें ख़त्म न होगीं बेशक ख़ुदा सब पर ग़ालिब (और) दाना (बीना) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,28,'Luqman','مَّا خَلۡقُكُمۡ وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡسࣲ وَٰحِدَةٍۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ','(خدا کو) تمہارا پیدا کرنا اور جِلا اُٹھانا ایک شخص (کے پیدا کرنے اور جلا اُٹھانے) کی طرح ہے۔ بیشک خدا سننے والا دیکھنے والا ہے','The creation and resurrection of you ˹all˺ is as simple ˹for Him˺ as that of a single soul. Surely Allah is All-Hearing, All-Seeing','तुम सबका पैदा करना और फिर (मरने के बाद) जिला उठाना एक शख्स के (पैदा करने और जिला उठाने के) बराबर है बेशक ख़ुदा (तुम सब की) सुनता और सब कुछ देख रहा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,29,'Luqman','أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ يَجۡرِيٓ إِلَىٰٓ أَجَلࣲ مُّسَمࣰّ ى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِيرࣱ‏','کیا تم نے نہیں دیکھا کہ خدا ہی رات کو دن میں داخل کرتا ہے اور (وہی) دن کو رات میں داخل کرتا ہے اور اُسی نے سورج اور چاند کو (تمہارے) زیر فرمان کر رکھا ہے۔ ہر ایک ایک وقتِ مقرر تک چل رہا ہے اور یہ کہ خدا تمہارے سب اعمال سے خبردار ہے','Do you not see that Allah causes the night to merge into the day and the day into the night, and has subjected the sun and the moon, each orbiting for an appointed term, and that Allah is All-Aware of what you do','क्या तूने ये भी ख्याल न किया कि ख़ुदा ही रात को (बढ़ा के) दिन में दाख़िल कर देता है (तो रात बढ़ जाती है) और दिन को (बढ़ा के) रात में दाख़िल कर देता है (तो दिन बढ़ जाता है) उसी ने आफताब व माहताब को (गोया) तुम्हारा ताबेए बना दिया है कि एक मुक़र्रर मीयाद तक (यूँ ही) चलता रहेगा और (क्या तूने ये भी ख्याल न किया कि) जो कुछ तुम करते हो ख़ुदा उससे ख़ूब वाकिफकार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,30,'Luqman','ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ','یہ اس لئے کہ خدا کی ذات برحق ہے اور جن کو یہ لوگ خدا کے سوا پکارتے ہیں وہ لغو ہیں اور یہ کہ خدا ہی عالی رتبہ اور گرامی قدر ہے','That is because Allah ˹alone˺ is the Truth and what they invoke besides Him is falsehood, and ˹because˺ Allah ˹alone˺ is the Most High, All-Great','ये (सब बातें) इस सबब से हैं कि ख़ुदा ही यक़ीनी बरहक़ (माबूद) है और उस के सिवा जिसको लोग पुकारते हैं यक़ीनी बिल्कुल बातिल और इसमें शक नहीं कि ख़ुदा ही आलीशान और बड़ा रुतबे वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,31,'Luqman','أَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ‏','کیا تم نے نہیں دیکھا کہ خدا ہی کی مہربانی سے کشتیاں دریا میں چلتی ہیں۔ تاکہ وہ تم کو اپنی کچھ نشانیاں دکھائے۔ بیشک اس میں ہر صبر کرنے والے (اور) شکر کرنے والے کے لئے نشانیاں ہیں','Do you not see that the ships sail ˹smoothly˺ through the sea by the grace of Allah so that He may show you some of His signs? Surely in this are signs for whoever is steadfast, grateful','क्या तूने इस पर भी ग़ौर नहीं किया कि ख़ुदा ही के फज़ल से कश्ती दरिया में बहती चलती रहती है ताकि (लकड़ी में ये क़ूवत देकर) तुम लोगों को अपनी (कुदरत की) बाज़ निशानियाँ दिखा दे बेशक उस में भी तमाम सब्र व शुक्र करने वाले (बन्दों) के लिए (कुदरत ख़ुदा की) बहुत सी निशानियाँ दिखा दे बेशक इसमें भी तमाम सब्र व शुक्र करने वाले (बन्दों) के लिए (क़ुदरते ख़ुदा की) बहुत सी निशानियाँ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,32,'Luqman','وَإِذَا غَشِيَهُم مَّوۡجࣱ كَٱلظُّلَلِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ فَمِنۡهُم مُّقۡتَصِدࣱۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا كُلُّ خَتَّارࣲ كَفُورࣲ‏','اور جب اُن پر (دریا کی) لہریں سائبانوں کی طرح چھا جاتی ہیں تو خدا کو پکارنے (اور) خالص اس کی عبادت کرنے لگتے ہیں پھر جب وہ اُن کو نجات دے کر خشکی پر پہنچا دیتا ہے تو بعض ہی انصاف پر قائم رہتے ہیں۔ اور ہماری نشانیوں سے وہی انکار کرتے ہیں جو عہد شکن اور ناشکرے ہیں','And as soon as they are overwhelmed by waves like mountains, they cry out to Allah ˹alone˺ in sincere devotion. But when He delivers them ˹safely˺ to shore, only some become relatively grateful. And none rejects Our signs except whoever is deceitful, ungrateful','और जब उन्हें मौज (ऊँची होकर) साएबानों की तरह (ऊपर से) ढॉक लेती है तो निरा खुरा उसी का अक़ीदा रखकर ख़ुदा को पुकारने लगते हैं फिर जब ख़ुदा उनको नजात देकर खुश्की तक पहुँचा देता है तो उनमें से बाज़ तो कुछ देर एतदाल पर रहते हैं (और बाज़ पक्के काफिर) और हमारी (क़ुदरत की) निशानियों से इन्कार तो बस बदएहद और नाशुक्रे ही लोग करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,33,'Luqman','يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡ وَٱخۡشَوۡاْ يَوۡمࣰ ا لَّا يَجۡزِي وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَيۡـًٔاۚ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ','لوگو اپنے پروردگار سے ڈرو اور اُس دن کا خوف کرو کہ نہ تو باپ اپنے بیٹے کے کچھ کام آئے۔ اور نہ بیٹا باپ کے کچھ کام آسکے۔ بیشک خدا کا وعدہ سچا ہے پس دنیا کی زندگی تم کو دھوکے میں نہ ڈال دے۔ اور نہ فریب دینے والا (شیطان) تمہیں خدا کے بارے میں کسی طرح کا فریب دے','O humanity! Be mindful of your Lord, and beware of a Day when no parent will be of any benefit to their child, nor will a child be of any benefit to their parent. Surely Allah’s promise is true. So do not let the life of this world deceive you, nor let the Chief Deceiver deceive you about Allah','लोगों अपने परवरदिगार से डरो और उस दिन का ख़ौफ रखो जब न कोई बाप अपने बेटे के काम आएगा और न कोई बेटा अपने बाप के कुछ काम आ सकेगा ख़ुदा का (क़यामत का) वायदा बिल्कुल पक्का है तो (कहीं) तुम लोगों को दुनिया की (चन्द रोज़ा) ज़िन्दगी धोखे में न डाले और न कहीं तुम्हें फरेब देने वाला (शैतान) कुछ फ़रेब दे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (31,34,'Luqman','إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَيُنَزِّلُ ٱلۡغَيۡثَ وَيَعۡلَمُ مَا فِي ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِي نَفۡسࣱ مَّاذَا تَكۡسِبُ غَدࣰ اۖ وَمَا تَدۡرِي نَفۡسُۢ بِأَيِّ أَرۡضࣲ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرُۢ','خدا ہی کو قیامت کا علم ہے اور وہی مینھہ برساتا ہے۔ اور وہی (حاملہ کے) پیٹ کی چیزوں کو جانتا ہے (کہ نر ہے یا مادہ) اور کوئی شخص نہیں جانتا کہ وہ کل کیا کام کرے گا۔ اور کوئی متنفس نہیں جانتا کہ کس سرزمین میں اُسے موت آئے گی بیشک خدا ہی جاننے والا (اور) خبردار ہے','Indeed, Allah ˹alone˺ has the knowledge of the Hour. He sends down the rain, and knows what is in the wombs. No soul knows what it will earn for tomorrow, and no soul knows in what land it will die. Surely Allah is All-Knowing, All-Aware','बेशक ख़ुदा ही के पास क़यामत (के आने) का इल्म है और वही (जब मौक़ा मुनासिब देखता है) पानी बरसाता है और जो कुछ औरतों के पेट में (नर मादा) है जानता है और कोई शख्स (इतना भी तो) नहीं जानता कि वह ख़़ुद कल क्या करेगा और कोई शख्स ये (भी) नहीं जानता है कि वह किस सर ज़मीन पर मरे (गड़े) गा बेशक ख़ुदा (सब बातों से) आगाह ख़बरदार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,1,'As-Sajda','الٓمٓ','الٓمٓ','Alif-Lãm-Mĩm','अलिफ़ लाम मीम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,2,'As-Sajda','تَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ','اس میں کچھ شک نہیں کہ اس کتاب کا نازل کیا جانا تمام جہان کے پروردگار کی طرف سے ہے','The revelation of this Book is—beyond doubt—from the Lord of all worlds','इसमे कुछ शक नहीं कि किताब क़ुरान का नाज़िल करना सारे जहाँ के परवरदिगार की तरफ से है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,3,'As-Sajda','أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۚ بَلۡ هُوَ ٱلۡحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوۡمࣰ ا مَّآ أَتَىٰهُم مِّن نَّذِيرࣲ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَهۡتَدُونَ','کیا یہ لوگ یہ کہتے ہیں کہ پیغمبر نے اس کو از خود بنا لیا ہے (نہیں) بلکہ وہ تمہارے پروردگار کی طرف سے برحق ہے تاکہ تم ان لوگوں کو ہدایت کرو جن کے پاس تم سے پہلے کوئی ہدایت کرنے والا نہیں آیا تاکہ یہ رستے پر چلیں','Or do they say, “He has fabricated it!”? No! It is the truth from your Lord in order for you to warn a people to whom no warner has come before you, so they may be ˹rightly˺ guided','क्या ये लोग (ये कहते हैं कि इसको इस शख्स (रसूल) ने अपनी जी से गढ़ लिया है नहीं ये बिल्कुल तुम्हारे परवरदिगार की तरफ से बरहक़ है ताकि तुम उन लोगों को (ख़ुदा के अज़ाब से) डराओ जिनके पास तुमसे पहले कोई डराने वाला आया ही नहीं ताकि ये लोग राह पर आएँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,4,'As-Sajda','ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِيࣲّ وَلَا شَفِيعٍۚ أَفَلَا تَتَذَكَّرُونَ','خدا ہی تو ہے جس نے آسمانوں اور زمین کو اور جو چیزیں ان دونوں میں ہیں سب کو چھ دن میں پیدا کیا پھر عرش پر جا ٹھہرا۔ اس کے سوا نہ تمہارا کوئی دوست ہے اور نہ سفارش کرنے والا۔ کیا تم نصیحت نہیں پکڑتے؟','It is Allah Who has created the heavens and the earth and everything in between in six Days, then established Himself on the Throne. You have no protector or intercessor besides Him. Will you not then be mindful','ख़ुदा ही तो है जिसने सारे आसमान और ज़मीन और जितनी चीज़े इन दोनो के दरमियान हैं छह: दिन में पैदा की फिर अर्श (के बनाने) पर आमादा हुआ उसके सिवा न कोई तुम्हारा सरपरस्त है न कोई सिफारिशी तो क्या तुम (इससे भी) नसीहत व इबरत हासिल नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,5,'As-Sajda','يُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَآءِ إِلَى ٱلۡأَرۡضِ ثُمَّ يَعۡرُجُ إِلَيۡهِ فِي يَوۡمࣲ كَانَ مِقۡدَارُهُۥٓ أَلۡفَ سَنَةࣲ مِّمَّا تَعُدُّونَ','وہی آسمان سے زمین تک (کے) ہر کام کا انتظام کرتا ہے۔ پھر وہ ایک روز جس کی مقدار تمہارے شمار کے مطابق ہزار برس ہوگی۔ اس کی طرف صعود (اور رجوع) کرے گا','He conducts every affair from the heavens to the earth, then it all ascends to Him on a Day whose length is a thousand years by your counting','आसमान से ज़मीन तक के हर अम्र का वही मुद्ब्बिर (व मुन्तज़िम) है फिर ये बन्दोबस्त उस दिन जिस की मिक़दार तुम्हारे शुमार से हज़ार बरस से होगी उसी की बारगाह में पेश होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,6,'As-Sajda','ذَٰلِكَ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡعَزِيزُ ٱلرَّحِيمُ','یہی تو پوشیدہ اور ظاہر کا جاننے والا (اور) غالب اور رحم والا (خدا) ہے','That is the Knower of the seen and unseen—the Almighty, Most Merciful','वही (मुदब्बिर) पोशीदा और ज़ाहिर का जानने वाला (सब पर) ग़ालिब मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,7,'As-Sajda','ٱلَّذِيٓ أَحۡسَنَ كُلَّ شَيۡءٍ خَلَقَهُۥۖ وَبَدَأَ خَلۡقَ ٱلۡإِنسَٰنِ مِن طِينࣲ‏','جس نے ہر چیز کو بہت اچھی طرح بنایا (یعنی) اس کو پیدا کیا۔ اور انسان کی پیدائش کو مٹی سے شروع کیا','Who has perfected everything He created. And He originated the creation of humankind from clay','वह (क़ादिर) जिसने जो चीज़ बनाई (निख सुख से) ख़ूब (दुरुस्त) बनाई और इन्सान की इबतेदाई ख़िलक़त मिट्टी से की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,8,'As-Sajda','ثُمَّ جَعَلَ نَسۡلَهُۥ مِن سُلَٰلَةࣲ مِّن مَّآءࣲ مَّهِينࣲ‏','پھر اس کی نسل خلاصے سے (یعنی) حقیر پانی سے پیدا کی','Then He made his descendants from an extract of a humble fluid','उसकी नस्ल (इन्सानी जिस्म के) खुलासा यानी (नुत्फे के से) ज़लील पानी से बनाई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,9,'As-Sajda','ثُمَّ سَوَّىٰهُ وَنَفَخَ فِيهِ مِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلࣰ ا مَّا تَشۡكُرُونَ','پھر اُس کو درست کیا پھر اس میں اپنی (طرف سے) روح پھونکی اور تمہارے کان اور آنکھیں اور دل بنائے مگر تم بہت کم شکر کرتے ہو','then He fashioned them and had a spirit of His Own ˹creation˺ breathed into them. And He gave you hearing, sight, and intellect. ˹Yet˺ you hardly give any thanks','फिर उस (के पुतले) को दुरुस्त किया और उसमें अपनी तरफ से रुह फूँकी और तुम लोगों के (सुनने के) लिए कान और (देखने के लिए) ऑंखें और (समझने के लिए) दिल बनाएँ (इस पर भी) तुम लोग बहुत कम शुक्र करते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,10,'As-Sajda','وَقَالُوٓاْ أَءِذَا ضَلَلۡنَا فِي ٱلۡأَرۡضِ أَءِنَّا لَفِي خَلۡقࣲ جَدِيدِۭۚ بَلۡ هُم بِلِقَآءِ رَبِّهِمۡ كَٰفِرُونَ','اور کہنے لگے کہ جب ہم زمین میں ملیامیٹ ہوجائیں گے تو کیا ازسرنو پیدا ہوں گے۔ حقیقت یہ ہے کہ یہ لوگ اپنے پروردگار کے سامنے جانے ہی کے قائل نہیں','˹Still˺ they ask ˹mockingly˺, “When we are disintegrated into the earth, will we really be raised as a new creation?” In fact, they are in denial of the meeting with their Lord','और ये लोग कहते हैं कि जब हम ज़मीन में नापैद हो जाएँगे तो क्या हम फिर नया जन्म लेगे (क़यामत से नही) बल्कि ये लोग अपने परवरदिगार के (सामने हुज़ूरी ही) से इन्कार रखते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,11,'As-Sajda','۞قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِي وُكِّلَ بِكُمۡ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ','کہہ دو کہ موت کا فرشتہ جو تم پر مقرر کیا گیا ہے تمہاری روحیں قبض کر لیتا ہے پھر تم اپنے پروردگار کی طرف لوٹائے جاؤ گے','Say, ˹O Prophet,˺ “Your soul will be taken by the Angel of Death, who is in charge of you. Then to your Lord you will ˹all˺ be returned.”','(ऐ रसूल) तुम कह दो कि मल्कुलमौत जो तुम्हारे ऊपर तैनात है वही तुम्हारी रुहें क़ब्ज़ करेगा उसके बाद तुम सबके सब अपने परवरदिगार की तरफ लौटाए जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,12,'As-Sajda','وَلَوۡ تَرَىٰٓ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُواْ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَآ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَٰلِحًا إِنَّا مُوقِنُونَ','اور تم (تعجب کرو) جب دیکھو کہ گنہگار اپنے پروردگار کے سامنے سرجھکائے ہوں گے (اور کہیں گے کہ) اے ہمارے پروردگار ہم نے دیکھ لیا اور سن لیا تو ہم کو (دنیا میں) واپس بھیج دے کہ نیک عمل کریں بیشک ہم یقین کرنے والے ہیں','If only you could see the wicked hanging their heads ˹in shame˺ before their Lord, ˹crying:˺ “Our Lord! We have now seen and heard, so send us back and we will do good. We truly have sure faith ˹now˺!”','और (ऐ रसूल) तुम को बहुत अफसोस होगा अगर तुम मुजरिमों को देखोगे कि वह (हिसाब के वक्त) अपने परवरदिगार की बारगाह में अपने सर झुकाए खड़े हैं और(अर्ज़ कर रहे हैं) परवरदिगार हमने (अच्छी तरह देखा और सुन लिया तू हमें दुनिया में एक दफा फिर लौटा दे कि हम नेक काम करें)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,13,'As-Sajda','وَلَوۡ شِئۡنَا لَأٓتَيۡنَا كُلَّ نَفۡسٍ هُدَىٰهَا وَلَٰكِنۡ حَقَّ ٱلۡقَوۡلُ مِنِّي لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِينَ','اور اگر ہم چاہتے تو ہر شخص کو ہدایت دے دیتے۔ لیکن میری طرف سے یہ بات قرار پاچکی ہے کہ میں دوزخ کو جنوں اور انسانوں سب سے بھردوں گا','Had We willed, We could have easily imposed guidance on every soul. But My Word will come to pass: I will surely fill up Hell with jinn and humans all together','और अब तो हमको (क़यामत का)े पूरा पूरा यक़ीन है और (ख़ुदा फरमाएगा कि) अगर हम चाहते तो दुनिया ही में हर शख़्श को (मजबूर करके) राहे रास्त पर ले आते मगर मेरी तरफ से (रोजे अज़ा) ये बात क़रार पा चुकी है कि मै जहन्नुम को जिन्नात और आदमियों से भर दूँगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,14,'As-Sajda','فَذُوقُواْ بِمَا نَسِيتُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَآ إِنَّا نَسِينَٰكُمۡۖ وَذُوقُواْ عَذَابَ ٱلۡخُلۡدِ بِمَا كُنتُمۡ تَعۡمَلُونَ','سو (اب آگ کے) مزے چکھو اس لئے کہ تم نے اُس دن کے آنے کو بھلا رکھا تھا (آج) ہم بھی تمہیں بھلا دیں گے اور جو کام تم کرتے تھے اُن کی سزا میں ہمیشہ کے عذاب کے مزے چکھتے رہو','So taste ˹the punishment˺ for neglecting the meeting of this Day of yours. We ˹too˺ will certainly neglect you. And taste the torment of eternity for what you used to do','तो चूँकि तुम आज के दिन हुज़ूरी को भूले बैठे थे तो अब उसका मज़ा चखो हमने तुमको क़सदन भुला दिया और जैसी जैसी तुम्हारी करतूतें थीं (उनके बदले) अब हमेशा के अज़ाब के मज़े चखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,15,'As-Sajda','إِنَّمَا يُؤۡمِنُ بِـَٔايَٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُواْ بِهَا خَرُّواْۤ سُجَّدࣰ اۤ وَسَبَّحُواْ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا يَسۡتَكۡبِرُونَ۩','ہماری آیتوں پر تو وہی لوگ ایمان لاتے ہیں کہ جب اُن کو اُن سے نصیحت کی جاتی ہے تو سجدے میں گرپڑتے اور اپنے پروردگار کی تعریف کے ساتھ تسبیح کرتے ہیں اور غرور نہیں کرتے','The only ˹true˺ believers in Our revelation are those who—when it is recited to them—fall into prostration and glorify the praises of their Lord and are not too proud','हमारी आयतों पर ईमान बस वही लोग लाते हैं कि जिस वक्त उन्हें वह (आयते) याद दिलायी गयीं तो फौरन सजदे में गिर पड़ने और अपने परवरदिगार की हम्दो सना की तस्बीह पढ़ने लगे और ये लोग तकब्बुर नही करते (15) (सजदा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,16,'As-Sajda','تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ يَدۡعُونَ رَبَّهُمۡ خَوۡفࣰ ا وَطَمَعࣰ ا وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ','اُن کے پہلو بچھونوں سے الگ رہتے ہیں (اور) وہ اپنے پروردگار کو خوف اور اُمید سے پکارتے اور جو (مال) ہم نے اُن کو دیا ہے اس میں سے خرچ کرتے ہیں','They abandon their beds, invoking their Lord with hope and fear, and donate from what We have provided for them','(रात) के वक्त उनके पहलू बिस्तरों से आशना नहीं होते और (अज़ाब के) ख़ौफ और (रहमत की) उम्मीद पर अपने परवरदिगार की इबादत करते हैं और हमने जो कुछ उन्हें अता किया है उसमें से (ख़ुदा की) राह में ख़र्च करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,17,'As-Sajda','فَلَا تَعۡلَمُ نَفۡسࣱ مَّآ أُخۡفِيَ لَهُم مِّن قُرَّةِ أَعۡيُنࣲ جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ','کوئی متنفس نہیں جانتا کہ اُن کے لئے کیسی آنکھوں کی ٹھنڈک چھپا کر رکھی گئی ہے۔ یہ ان اعمال کا صلہ ہے جو وہ کرتے تھے','No soul can imagine what delights are kept in store for them as a reward for what they used to do','उन लोगों की कारगुज़ारियों के बदले में कैसी कैसी ऑंखों की ठन्डक उनके लिए ढकी छिपी रखी है उसको कोई शख़्श जानता ही नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,18,'As-Sajda','أَفَمَن كَانَ مُؤۡمِنࣰ ا كَمَن كَانَ فَاسِقࣰ اۚ لَّا يَسۡتَوُۥنَ','بھلا جو مومن ہو وہ اس شخص کی طرح ہوسکتا ہے جو نافرمان ہو؟ دونوں برابر نہیں ہو سکتے','Is the one who is a believer equal ˹before Allah˺ to the one who is rebellious? They are not equal','तो क्या जो शख़्श ईमानदार है उस शख़्श के बराबर हो जाएगा जो बदकार है (हरगिज़ नहीं) ये दोनों बराबर नही हो सकते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,19,'As-Sajda','أَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَلَهُمۡ جَنَّٰتُ ٱلۡمَأۡوَىٰ نُزُلَۢا بِمَا كَانُواْ يَعۡمَلُونَ','جو لوگ ایمان لائے اور نیک عمل کرتے رہے اُن کے (رہنے کے) لئے باغ ہیں یہ مہمانی اُن کاموں کی جزا ہے جو وہ کرتے تھے','As for those who believe and do good, they will have the Gardens of ˹Eternal˺ Residence—as an accommodation for what they used to do','लेकिन जो लोग ईमान लाए और उन्होंने अच्छे अच्छे काम किए उनके लिए तो रहने सहने के लिए (बेहश्त के) बाग़ात हैं ये सामाने ज़ियाफ़त उन कारगुज़ारियों का बदला है जो वह (दुनिया में) कर चुके थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,20,'As-Sajda','وَأَمَّا ٱلَّذِينَ فَسَقُواْ فَمَأۡوَىٰهُمُ ٱلنَّارُۖ كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَآ أُعِيدُواْ فِيهَا وَقِيلَ لَهُمۡ ذُوقُواْ عَذَابَ ٱلنَّارِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ','اور جنہوں نے نافرمانی کی اُن کے رہنے کے لئے دوزخ ہے جب چاہیں گے کہ اس میں سے نکل جائیں تو اس میں لوٹا دیئے جائیں گے۔ اور اُن سے کہا جائے گا کہ جس دوزخ کے عذاب کو تم جھوٹ سمجھتے تھے اس کے مزے چکھو','But as for those who are rebellious, the Fire will be their home. Whenever they try to escape from it, they will be forced back into it, and will be told, “Taste the Fire’s torment, which you used to deny.”','और जिन लोगों ने बदकारी की उनका ठिकाना तो (बस) जहन्नुम है वह जब उसमें से निकल जाने का इरादा करेंगे तो उसी में फिर ढकेल दिए जाएँगे और उन से कहा जाएगा कि दोज़ख़ के जिस अज़ाब को तुम झुठलाते थे अब उसके मज़े चखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,21,'As-Sajda','وَلَنُذِيقَنَّهُم مِّنَ ٱلۡعَذَابِ ٱلۡأَدۡنَىٰ دُونَ ٱلۡعَذَابِ ٱلۡأَكۡبَرِ لَعَلَّهُمۡ يَرۡجِعُونَ','اور ہم اُن کو (قیامت کے) بڑے عذاب کے سوا عذاب دنیا کا بھی مزہ چکھائیں گے۔ شاید (ہماری طرف) لوٹ آئیں','We will certainly make them taste some of the minor torment ˹in this life˺ before the major torment ˹of the Hereafter˺, so perhaps they will return ˹to the Right Path˺','और हम यक़ीनी (क़यामत के) बड़े अज़ाब से पहले दुनिया के (मामूली) अज़ाब का मज़ा चखाएँगें जो अनक़रीब होगा ताकि ये लोग अब भी (मेरी तरफ) रुज़ू करें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,22,'As-Sajda','وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَآۚ إِنَّا مِنَ ٱلۡمُجۡرِمِينَ مُنتَقِمُونَ','اور اس شخص سے بڑھ کر ظالم کون جس کو اس کے پروردگار کی آیتوں سے نصیحت کی جائے تو وہ اُن سے منہ پھیر لے۔ ہم گنہگاروں سے ضرور بدلہ لینے والے ہیں','And who does more wrong than the one who is reminded of Allah’s revelations then turns away from them? We will surely inflict punishment upon the wicked','और जिस शख़्श को उसके परवरदिगार की आयतें याद दिलायी जाएँ और वह उनसे मुँह फेर उससे बढ़कर और ज़ालिम कौन होगा हम गुनाहगारों से इन्तक़ाम लेगें और ज़रुर लेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,23,'As-Sajda','وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَلَا تَكُن فِي مِرۡيَةࣲ مِّن لِّقَآئِهِۦۖ وَجَعَلۡنَٰهُ هُدࣰ ى لِّبَنِيٓ إِسۡرَٰٓءِيلَ','اور ہم نے موسٰی کو کتاب دی تو تم اُن کے ملنے سے شک میں نہ ہونا اور ہم نے اس (کتاب) کو (یا موسٰی کو) بنی اسرائیل کے لئے (ذریعہ) ہدایت بنایا','Indeed, We gave the Scripture to Moses—so let there be no doubt ˹O Prophet˺ that you ˹too˺ are receiving revelations—and We made it a guide for the Children of Israel','और (ऐ रसूल) हमने तो मूसा को भी (आसमानी किताब) तौरेत अता की थी तुम भी इस किताब (कुरान) के (अल्लाह की तरफ से) मिलने में शक में न पड़े रहो और हमने इस (तौरेत) तो तुम को भी बनी इसराईल के लिए रहनुमा क़रार दिया था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,24,'As-Sajda','وَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةࣰ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ','اور ان میں سے ہم نے پیشوا بنائے تھے جو ہمارے حکم سے ہدایت کیا کرتے تھے۔ جب وہ صبر کرتے تھے اور وہ ہماری آیتوں پر یقین رکھتے تھے','We raised from among them leaders, guiding by Our command, when they patiently endured and firmly believed in Our signs','और उन्ही (बनी इसराईल) में से हमने कुछ लोगों को चूंकि उन्होंने (मुसीबतों पर) सब्र किया था पेशवा बनाया जो हमारे हुक्म से (लोगो की) हिदायत करते थे और (इसके अलावा) हमारी आयतो का दिल से यक़ीन रखते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,25,'As-Sajda','إِنَّ رَبَّكَ هُوَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ','بلاشبہ تمہارا پروردگار ان میں جن باتوں میں وہ اختلاف کرتے تھے۔ قیامت کے روز فیصلہ کر دے گا','Indeed, your Lord will decide between them on the Day of Judgment regarding their differences','(ऐ रसूल) हसमें शक़ नहीं कि जिन बातों में लोग (दुनिया में) बाहम झगड़ते रहते हैं क़यामत के दिन तुम्हारा परवरदिगार क़तई फैसला कर देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,26,'As-Sajda','أَوَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٍۚ أَفَلَا يَسۡمَعُونَ','کیا اُن کو اس (امر) سے ہدایت نہ ہوئی کہ ہم نے اُن سے پہلے بہت سی اُمتوں کو جن کے مقامات سکونت میں یہ چلتے پھرتے ہیں ہلاک کر دیا۔ بیشک اس میں نشانیاں ہیں۔ تو یہ سنتے کیوں نہیں','Is it not yet clear to them how many peoples We destroyed before them, whose ruins they still pass by? Surely in this are signs. Will they not then listen','क्या उन लोगों को ये मालूम नहीं कि हमने उनसे पहले कितनी उम्मतों को हलाक कर डाला जिन के घरों में ये लोग चल फिर रहें हैं बेशक उसमे (कुदरते ख़ुदा की) बहुत सी निशानियाँ हैं तो क्या ये लोग सुनते नहीं हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,27,'As-Sajda','أَوَلَمۡ يَرَوۡاْ أَنَّا نَسُوقُ ٱلۡمَآءَ إِلَى ٱلۡأَرۡضِ ٱلۡجُرُزِ فَنُخۡرِجُ بِهِۦ زَرۡعࣰ ا تَأۡكُلُ مِنۡهُ أَنۡعَٰمُهُمۡ وَأَنفُسُهُمۡۚ أَفَلَا يُبۡصِرُونَ','کیا اُنہوں نے نہیں دیکھا کہ ہم بنجر زمین کی طرف پانی رواں کرتے ہیں پھر اس سے کھیتی پیدا کرتے ہیں جس میں سے ان کے چوپائے بھی کھاتے ہیں اور وہ خود بھی (کھاتے ہیں) تو یہ دیکھتے کیوں نہیں۔','Do they not see how We drive rain to parched land, producing ˹various˺ crops from which they and their cattle eat? Will they not then see','क्या इन लोगों ने इस पर भी ग़ौर नहीं किया कि हम चटियल मैदान (इफ़तादा) ज़मीन की तरफ पानी को जारी करते हैं फिर उसके ज़रिए से हम घास पात लगाते हैं जिसे उनके जानवर और ये ख़ुद भी खाते हैं तो क्या ये लोग इतना भी नहीं देखते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,28,'As-Sajda','وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡفَتۡحُ إِن كُنتُمۡ صَٰدِقِينَ','اور کہتے ہیں اگر تم سچے ہو تو یہ فیصلہ کب ہوگا؟','They ask ˹mockingly˺, “When is this ˹Day of final˺ Decision, if what you say is true?”','और ये लोग कहते है कि अगर तुम लोग सच्चे हो (कि क़यामत आएगी) तो (आख़िर) ये फैसला कब होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,29,'As-Sajda','قُلۡ يَوۡمَ ٱلۡفَتۡحِ لَا يَنفَعُ ٱلَّذِينَ كَفَرُوٓاْ إِيمَٰنُهُمۡ وَلَا هُمۡ يُنظَرُونَ','کہہ دو کہ فیصلے کے دن کافروں کو ان کا ایمان لانا کچھ بھی فائدہ نہ دے گا اور نہ اُن کو مہلت دی جائے گی','Say, ˹O Prophet,˺ “On the Day of Decision it will not benefit the disbelievers to believe then, nor will they be delayed ˹from punishment˺.”','(ऐ रसूल) तुम कह दो कि फैसले के दिन कुफ्फ़ार को उनका ईमान लाना कुछ काम न आएगा और न उनको (इसकी) मोहलत दी जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (32,30,'As-Sajda','فَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ','تو اُن سے منہ پھیر لو اور انتظار کرو یہ بھی انتظار کر رہے ہیں','So turn away from them, and wait! They too are waiting','ग़रज़ तुम उनकी बातों का ख्याल छोड़ दो और तुम मुन्तज़िर रहो (आख़िर) वह लोग भी तो इन्तज़ार कर रहे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,1,'Al-Ahzaab','يَٰٓأَيُّهَا ٱلنَّبِيُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمࣰ ا','اے پیغمبر خدا سے ڈرتے رہنا اور کافروں اور منافقوں کا کہا نہ ماننا۔ بےشک خدا جاننے والا اور حکمت والا ہے','O Prophet! ˹Always˺ be mindful of Allah, and do not yield to the disbelievers and the hypocrites. Indeed, Allah is All-Knowing, All-Wise','ऐ नबी खुदा ही से डरते रहो और काफिरों और मुनाफिक़ों की बात न मानो इसमें शक नहीं कि खुदा बड़ा वाक़िफकार हकीम है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,2,'Al-Ahzaab','وَٱتَّبِعۡ مَا يُوحَىٰٓ إِلَيۡكَ مِن رَّبِّكَۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرࣰ ا','اور جو (کتاب) تم کو تمہارے پروردگار کی طرف سے وحی کی جاتی ہے اُسی کی پیروی کئے جانا۔ بےشک خدا تمہارے سب عملوں سے خبردار ہے','Follow what is revealed to you from your Lord. Surely Allah is All-Aware of what you ˹all˺ do','और तुम्हारे परवरदिगार की तरफ से तुम्हारे पास जो ''''वही'''' की जाती है (बस) उसी की पैरवी करो तुम लोग जो कुछ कर रहे हो खुदा उससे यक़ीनी अच्छा तरह आगाह है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,3,'Al-Ahzaab','وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلࣰ ا','اور خدا پر بھروسہ رکھنا۔ اور خدا ہی کارساز کافی ہے','And put your trust in Allah, for Allah is sufficient as a Trustee of Affairs','और खुदा ही पर भरोसा रखो और खुदा ही कारसाजी के लिए काफी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,4,'Al-Ahzaab','مَّا جَعَلَ ٱللَّهُ لِرَجُلࣲ مِّن قَلۡبَيۡنِ فِي جَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَٰجَكُمُ ٱلَّٰٓـِٔي تُظَٰهِرُونَ مِنۡهُنَّ أُمَّهَٰتِكُمۡۚ وَمَا جَعَلَ أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ يَقُولُ ٱلۡحَقَّ وَهُوَ يَهۡدِي ٱلسَّبِيلَ','خدا نے کسی آدمی کے پہلو میں دو دل نہیں بنائے۔ اور نہ تمہاری عورتوں کو جن کو تم ماں کہہ بیٹھتے ہو تمہاری ماں بنایا اور نہ تمہارے لے پالکوں کو تمہارے بیٹے بنایا۔ یہ سب تمہارے منہ کی باتیں ہیں۔ اور خدا تو سچی بات فرماتا ہے اور وہی سیدھا رستہ دکھاتا ہے','Allah does not place two hearts in any person’s chest. Nor does He regard your wives as ˹unlawful for you like˺ your real mothers, ˹even˺ if you say they are. Nor does He regard your adopted children as your real children. These are only your baseless assertions. But Allah declares the truth, and He ˹alone˺ guides to the ˹Right˺ Way','ख़ुदा ने किसी आदमी के सीने में दो दिल नहीं पैदा किये कि (एक ही वक्त दो इरादे कर सके) और न उसने तुम्हारी बीवियों को जिन से तुम जेहार करते हो तुम्हारी माएँ बना दी और न उसने तुम्हारे लिये पालकों को तुम्हारे बेटे बना दिये। ये तो फ़क़त तुम्हारी मुँह बोली बात (और ज़ुबानी जमा खर्च) है और (चाहे किसी को बुरी लगे या अच्छी) खुदा तो सच्ची कहता है और सीधी राह दिखाता है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,5,'Al-Ahzaab','ٱدۡعُوهُمۡ لِأٓبَآئِهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوٓاْ ءَابَآءَهُمۡ فَإِخۡوَٰنُكُمۡ فِي ٱلدِّينِ وَمَوَٰلِيكُمۡۚ وَلَيۡسَ عَلَيۡكُمۡ جُنَاحࣱ فِيمَآ أَخۡطَأۡتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورࣰ ا رَّحِيمًا','مومنو! لےپالکوں کو اُن کے (اصلی) باپوں کے نام سے پکارا کرو۔ کہ خدا کے نزدیک یہی بات درست ہے۔ اگر تم کو اُن کے باپوں کے نام معلوم نہ ہوں تو دین میں وہ تمہارے بھائی اور دوست ہیں اور جو بات تم سے غلطی سے ہوگئی ہو اس میں تم پر کچھ گناہ نہیں۔ لیکن جو قصد دلی سے کرو (اس پر مواخذہ ہے) اور خدا بخشنے والا مہربان ہے','Let your adopted children keep their family names. That is more just in the sight of Allah. But if you do not know their fathers, then they are ˹simply˺ your fellow believers and close associates. There is no blame on you for what you do by mistake, but ˹only˺ for what you do intentionally. And Allah is All-Forgiving, Most Merciful','लिये पालकों का उनके (असली) बापों के नाम से पुकारा करो यही खुदा के नज़दीक बहुत ठीक है हाँ अगर तुम लोग उनके असली बापों को न जानते हो तो तुम्हारे दीनी भाई और दोस्त हैं (उन्हें भाई या दोस्त कहकर पुकारा करो) और हाँ इसमें भूल चूक जाओ तो अलबत्ता उसका तुम पर कोई इल्ज़ाम नहीं है मगर जब तुम दिल से जानबूझ कर करो (तो ज़रूर गुनाह है) और खुदा तो बड़ा बख्शने वाला मेहरबान है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,6,'Al-Ahzaab','ٱلنَّبِيُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِينَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَٰجُهُۥٓ أُمَّهَٰتُهُمۡۗ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضࣲ فِي كِتَٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُهَٰجِرِينَ إِلَّآ أَن تَفۡعَلُوٓاْ إِلَىٰٓ أَوۡلِيَآئِكُم مَّعۡرُوفࣰ اۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورࣰ ا','پیغمبر مومنوں پر اُن کی جانوں سے بھی زیادہ حق رکھتے ہیں اور پیغمبر کی بیویاں اُن کی مائیں ہیں۔ اور رشتہ دار آپس میں کتاب الله کے رُو سے مسلمانوں اور مہاجروں سے ایک دوسرے (کے ترکے) کے زیادہ حقدار ہیں۔ مگر یہ کہ تم اپنے دوستوں سے احسان کرنا چاہو۔ (تو اور بات ہے) ۔ یہ حکم کتاب یعنی (قرآن) میں لکھ دیا گیا ہے','The Prophet has a stronger affinity to the believers than they do themselves. And his wives are their mothers. As ordained by Allah, blood relatives are more entitled ˹to inheritance˺ than ˹other˺ believers and immigrants, unless you ˹want to˺ show kindness to your ˹close˺ associates ˹through bequest˺. This is decreed in the Record','नबी तो मोमिनीन से खुद उनकी जानों से भी बढ़कर हक़ रखते हैं (क्योंकि वह गोया उम्मत के मेहरबान बाप हैं) और उनकी बीवियाँ (गोया) उनकी माएँ हैं और मोमिनीन व मुहाजिरीन में से (जो लोग बाहम) क़राबतदार हैं। किताबें खुदा की रूह से (ग़ैरों की निस्बत) एक दूसरे के (तर्के के) ज्यादा हक़दार हैं मगर (जब) तुम अपने दोस्तों के साथ सुलूक करना चाहो (तो दूसरी बात है) ये तो किताबे (खुदा) में लिखा हुआ (मौजूद) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,7,'Al-Ahzaab','وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحࣲ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظࣰ ا','اور جب ہم نے پیغمبروں سے عہد لیا اور تم سے نوح سے اور ابراہیم سے اور موسیٰ سے اور مریم کے بیٹے عیسیٰ سے۔ اور عہد بھی اُن سے پکّا لیا','And ˹remember˺ when We took a covenant from the prophets, as well as from you ˹O Prophet˺, and from Noah, Abraham, Moses, and Jesus, son of Mary. We did take a solemn covenant from ˹all of˺ them','और (ऐ रसूल वह वक्त याद करो) जब हमने और पैग़म्बरों से और ख़ास तुमसे और नूह और इबराहीम और मूसा और मरियम के बेटे ईसा से एहदो पैमाने लिया और उन लोगों से हमने सख्त एहद लिया था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,8,'Al-Ahzaab','لِّيَسۡـَٔلَ ٱلصَّٰدِقِينَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَٰفِرِينَ عَذَابًا أَلِيمࣰ ا','تاکہ سچ کہنے والوں سے اُن کی سچائی کے بارے میں دریافت کرے اور اس نے کافروں کے لئے دکھ دینے والا عذاب تیار کر رکھا ہے','so that He may question these men of truth about their ˹delivery of the˺ truth. And He has prepared a painful punishment for the disbelievers','ताकि (क़यामत के दिन) सच्चों (पैग़म्बरों) से उनकी सच्चाई तबलीग़े रिसालत का हाल दरियाफ्त करें और काफिरों के वास्ते तो उसने दर्दनाक अज़ाब तैयार ही कर रखा है।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,9,'Al-Ahzaab','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ نِعۡمَةَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ جَآءَتۡكُمۡ جُنُودࣱ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحࣰ ا وَجُنُودࣰ ا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا','مومنو خدا کی اُس مہربانی کو یاد کرو جو (اُس نے) تم پر (اُس وقت کی) جب فوجیں تم پر (حملہ کرنے کو) آئیں۔ تو ہم نے اُن پر ہوا بھیجی اور ایسے لشکر (نازل کئے) جن کو تم دیکھ نہیں سکتے تھے۔ اور جو کام تم کرتے ہو خدا اُن کو دیکھ رہا ہے','O believers! Remember Allah’s favour upon you when ˹enemy˺ forces came to ˹besiege˺ you ˹in Medina˺, so We sent against them a ˹bitter˺ wind and forces you could not see. And Allah is All-Seeing of what you do','(ऐ ईमानदारों खुदा की) उन नेअमतों को याद करो जो उसने तुम पर नाज़िल की हैं (जंगे खन्दक में) जब तुम पर (काफिरों का) लशकर (उमड़ के) आ पड़ा तो (हमने तुम्हारी मदद की) उन पर ऑंधी भेजी और (इसके अलावा फरिश्तों का ऐसा लश्कर भेजा) जिसको तुमने देखा तक नहीं और तुम जो कुछ कर रहे थे खुदा उसे खूब देख रहा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,10,'Al-Ahzaab','إِذۡ جَآءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠','جب وہ تمہارے اُوپر اور نیچے کی طرف سے تم پر چڑھ آئے اور جب آنکھیں پھر گئیں اور دل (مارے دہشت کے) گلوں تک پہنچ گئے اور تم خدا کی نسبت طرح طرح کے گمان کرنے لگے','˹Remember˺ when they came at you from east and west, when your eyes grew wild ˹in horror˺ and your hearts jumped into your throats, and you entertained ˹conflicting˺ thoughts about Allah','जिस वक्त वह लोग तुम पर तुम्हारे ऊपर से आ पड़े और तुम्हारे नीचे की तरफ से भी पिल गए और जिस वक्त (उनकी कसरत से) तुम्हारी ऑंखें ख़ैरा हो गयीं थी और (ख़ौफ से) कलेजे मुँह को आ गए थे और ख़ुदा पर तरह-तरह के (बुरे) ख्याल करने लगे थे।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,11,'Al-Ahzaab','هُنَالِكَ ٱبۡتُلِيَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُواْ زِلۡزَالࣰ ا شَدِيدࣰ ا','وہاں مومن آزمائے گئے اور سخت طور پر ہلائے گئے','Then and there the believers were put to the test, and were violently shaken','यहाँ पर मोमिनों का इम्तिहान लिया गया था और ख़ूब अच्छी तरह झिंझोड़े गए थे।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,12,'Al-Ahzaab','وَإِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضࣱ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورࣰ ا','اور جب منافق اور وہ لوگ جن کے دلوں میں بیماری ہے کہنے لگے کہ خدا اور اس کے رسول نے ہم سے محض دھوکے کا وعدہ کیا تھا','And ˹remember˺ when the hypocrites and those with sickness in their hearts said, “Allah and His Messenger have promised us nothing but delusion!”','और जिस वक्त मुनाफेक़ीन और वह लोग जिनके दिलों में (कुफ्र का) मरज़ था कहने लगे थे कि खुदा ने और उसके रसूल ने जो हमसे वायदे किए थे वह बस बिल्कुल धोखे की टट्टी था।');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,13,'Al-Ahzaab','وَإِذۡ قَالَت طَّآئِفَةࣱ مِّنۡهُمۡ يَٰٓأَهۡلَ يَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُواْۚ وَيَسۡتَـٔۡذِنُ فَرِيقࣱ مِّنۡهُمُ ٱلنَّبِيَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوۡرَةࣱ وَمَا هِيَ بِعَوۡرَةٍۖ إِن يُرِيدُونَ إِلَّا فِرَارࣰ ا','اور جب اُن میں سے ایک جماعت کہتی تھی کہ اے اہل مدینہ (یہاں) تمہارے ٹھہرنے کا مقام نہیں تو لوٹ چلو۔ اور ایک گروہ ان میں سے پیغمبر سے اجازت مانگنے اور کہنے لگا کہ ہمارے گھر کھلے پڑے ہیں حالانکہ وہ کھلے نہیں تھے۔ وہ تو صرف بھاگنا چاہتے تھے','And ˹remember˺ when a group of them said, “O people of Yathrib! There is no point in you staying ˹here˺, so retreat!” Another group of them asked the Prophet’s permission ˹to leave˺, saying, “Our homes are vulnerable,” while ˹in fact˺ they were not vulnerable. They only wished to flee','और अब उनमें का एक गिरोह कहने लगा था कि ऐ मदीने वालों अब (दुश्मन के मुक़ाबलें में ) तुम्हारे कहीं ठिकाना नहीं तो (बेहतर है कि अब भी) पलट चलो और उनमें से कुछ लोग रसूल से (घर लौट जाने की) इजाज़त माँगने लगे थे कि हमारे घर (मर्दों से) बिल्कुल ख़ाली (गैर महफूज़) पड़े हुए हैं - हालाँकि वह ख़ाली (ग़ैर महफूज़) न थे (बल्कि) वह लोग तो (इसी बहाने से) बस भागना चाहते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,14,'Al-Ahzaab','وَلَوۡ دُخِلَتۡ عَلَيۡهِم مِّنۡ أَقۡطَارِهَا ثُمَّ سُئِلُواْ ٱلۡفِتۡنَةَ لَأٓتَوۡهَا وَمَا تَلَبَّثُواْ بِهَآ إِلَّا يَسِيرࣰ ا','اور اگر (فوجیں) اطراف مدینہ سے ان پر آ داخل ہوں پھر اُن سے خانہ جنگی کے لئے کہا جائے تو (فوراً) کرنے لگیں اور اس کے لئے بہت ہی کم توقف کریں','Had their city been sacked from all sides and they had been asked to abandon faith, they would have done so with little hesitation','और अगर ऐसा ही लश्कर उन लोगों पर मदीने के एतराफ से आ पड़े और उन से फसाद (ख़ाना जंगी) करने की दरख्वास्त की जाए तो ये लोग उसके लिए (फौरन) आ मौजूद हों');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,15,'Al-Ahzaab','وَلَقَدۡ كَانُواْ عَٰهَدُواْ ٱللَّهَ مِن قَبۡلُ لَا يُوَلُّونَ ٱلۡأَدۡبَٰرَۚ وَكَانَ عَهۡدُ ٱللَّهِ مَسۡـُٔولࣰ ا','حالانکہ پہلے خدا سے اقرار کر چکے تھے کہ پیٹھ نہیں پھریں گے۔ اور خدا سے (جو) اقرار (کیا جاتا ہے اُس کی) ضرور پرسش ہوگی','They had already pledged to Allah earlier never to turn their backs ˹in retreat˺. And a pledge to Allah must be answered for','और (उस वक्त) अपने घरों में भी बहुत कम तवक्क़ुफ़ करेंगे (मगर ये तो जिहाद है) हालाँकि उन लोगों ने पहले ही खुदा से एहद किया था कि हम दुश्मन के मुक़ाबले में (अपनी) पीठ न फेरेंगे और खुदा के एहद की पूछगछ तो (एक न एक दिन) होकर रहेगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,16,'Al-Ahzaab','قُل لَّن يَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذࣰ ا لَّا تُمَتَّعُونَ إِلَّا قَلِيلࣰ ا','کہہ دو کہ اگر تم مرنے یا مارے سے بھاگتے ہو تو بھاگنا تم کو فائدہ نہیں دے گا اور اس وقت تم بہت ہی کم فائدہ اٹھاؤ گے','Say, ˹O Prophet,˺ “Fleeing will not benefit you if you ˹try to˺ escape a natural or violent death. ˹If it is not your time,˺ you will only be allowed enjoyment for a little while.”','(ऐ रसूल उनसे) कह दो कि अगर तुम मौत का क़त्ल (के ख़ौफ) से भागे भी तो (यह) भागना तुम्हें हरगिज़ कुछ भी मुफ़ीद न होगा और अगर तुम भागकर बच भी गए तो बस यही न की दुनिया में चन्द रोज़ा और चैनकर लो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,17,'Al-Ahzaab','قُلۡ مَن ذَا ٱلَّذِي يَعۡصِمُكُم مِّنَ ٱللَّهِ إِنۡ أَرَادَ بِكُمۡ سُوٓءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةࣰۚ وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيࣰّ ا وَلَا نَصِيرࣰ ا','کہہ دو کہ اگر خدا تمہارے ساتھ برائی کا ارادہ کرے تو کون تم کو اس سے بچا سکتا ہے یا اگر تم پر مہربانی کرنی چاہے تو (کون اس کو ہٹا سکتا ہے) اور یہ لوگ خدا کے سوا کسی کو نہ اپنا دوست پائیں گے اور نہ مددگار','Ask ˹them, O Prophet˺, “Who can put you out of Allah’s reach if He intends to harm you or show you mercy?” They can never find any protector or helper besides Allah','(ऐ रसूल) तुम उनसे कह दो कि अगर खुदा तुम्हारे साथ बुराई का इरादा कर बैठे तो तुम्हें उसके (अज़ाब) से कौन ऐसा है जो बचाए या भलाई ही करना चाहे (तो कौन रोक सकता है) और ये लोग खुदा के सिवा न तो किसी को अपना सरपरस्त पाएँगे और न मद्दगार');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,18,'Al-Ahzaab','۞قَدۡ يَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِينَ مِنكُمۡ وَٱلۡقَآئِلِينَ لِإِخۡوَٰنِهِمۡ هَلُمَّ إِلَيۡنَاۖ وَلَا يَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِيلًا','خدا تم میں سے ان لوگوں کو بھی جانتا ہے جو (لوگوں کو) منع کرتے ہیں اور اپنے بھائیوں سے کہتے ہیں کہ ہمارے پاس چلے آؤ۔ اور لڑائی میں نہیں آتے مگر کم','Allah knows well those among you who discourage ˹others from fighting˺, saying ˹secretly˺ to their brothers, “Stay with us,” and who themselves hardly take part in fighting','तुममें से जो लोग (दूसरों को जिहाद से) रोकते हैं खुदा उनको खूब जानता है और (उनको भी खूब जानता है) जो अपने भाई बन्दों से कहते हैं कि हमारे पास चले भी आओ और खुद भी (फक़त पीछा छुड़ाने को लड़ाई के खेत) में बस एक ज़रा सा आकर तुमसे अपनी जान चुराई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,19,'Al-Ahzaab','أَشِحَّةً عَلَيۡكُمۡۖ فَإِذَا جَآءَ ٱلۡخَوۡفُ رَأَيۡتَهُمۡ يَنظُرُونَ إِلَيۡكَ تَدُورُ أَعۡيُنُهُمۡ كَٱلَّذِي يُغۡشَىٰ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَإِذَا ذَهَبَ ٱلۡخَوۡفُ سَلَقُوكُم بِأَلۡسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلۡخَيۡرِۚ أُوْلَٰٓئِكَ لَمۡ يُؤۡمِنُواْ فَأَحۡبَطَ ٱللَّهُ أَعۡمَٰلَهُمۡۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣰ ا','(یہ اس لئے کہ) تمہارے بارے میں بخل کرتے ہیں۔ پھر جب ڈر (کا وقت) آئے تو تم ان کو دیکھو کہ تمہاری طرف دیکھ رہے ہیں (اور) اُن کی آنکھیں (اسی طرح) پھر رہی ہیں جیسے کسی کو موت سے غشی آرہی ہو۔ پھر جب خوف جاتا رہے تو تیز زبانوں کے ساتھ تمہارے بارے میں زبان درازی کریں اور مال میں بخل کریں۔ یہ لوگ (حقیقت میں) ایمان لائے ہی نہ تھے تو خدا نے ان کے اعمال برباد کر دیئے۔ اور یہ خدا کو آسان تھا','˹They are˺ totally unwilling to assist you. When danger comes, you see them staring at you with their eyes rolling like someone in the throes of death. But once the danger is over, they slash you with razor-sharp tongues, ravenous for ˹worldly˺ gains. Such people have not ˹truly˺ believed, so Allah has rendered their deeds void. And that is easy for Allah','और चल दिए और जब (उन पर) कोई ख़ौफ (का मौक़ा) आ पड़ा तो देखते हो कि (आस से) तुम्हारी तरफ देखते हैं (और) उनकी ऑंखें इस तरह घूमती हैं जैसे किसी शख्स पर मौत की बेहोशी छा जाए फिर वह ख़ौफ (का मौक़ा) जाता रहा और ईमानदारों की फतेह हुई तो माले (ग़नीमत) पर गिरते पड़ते फौरन तुम पर अपनी तेज़ ज़बानों से ताना कसने लगे ये लोग (शुरू) से ईमान ही नहीं लाए (फक़त ज़बानी जमा ख़र्च थी) तो खुदा ने भी इनका किया कराया सब अकारत कर दिया और ये तो खुदा के वास्ते एक (निहायत) आसान बात थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,20,'Al-Ahzaab','يَحۡسَبُونَ ٱلۡأَحۡزَابَ لَمۡ يَذۡهَبُواْۖ وَإِن يَأۡتِ ٱلۡأَحۡزَابُ يَوَدُّواْ لَوۡ أَنَّهُم بَادُونَ فِي ٱلۡأَعۡرَابِ يَسۡـَٔلُونَ عَنۡ أَنۢبَآئِكُمۡۖ وَلَوۡ كَانُواْ فِيكُم مَّا قَٰتَلُوٓاْ إِلَّا قَلِيلࣰ ا','(خوف کے سبب) خیال کرتے ہیں کہ فوجیں نہیں گئیں۔ اور اگر لشکر آجائیں تو تمنا کریں کہ (کاش) گنواروں میں جا رہیں (اور) تمہاری خبر پوچھا کریں۔ اور اگر تمہارے درمیان ہوں تو لڑائی نہ کریں مگر کم','They ˹still˺ think that the enemy alliance has not ˹yet˺ withdrawn. And if the allies were to come ˹again˺, the hypocrites would wish to be away in the desert among nomadic Arabs, ˹only˺ asking for news about you ˹believers˺. And if the hypocrites were in your midst, they would hardly take part in the fight','(मदीने का मुहासेरा करने वाले चल भी दिए मगर) ये लोग अभी यही समझ रहे हैं कि (काफ़िरों के) लश्कर अभी नहीं गए और अगर कहीं (कुफ्फार का) लश्कर फिर आ पहुँचे तो ये लोग चाहेंगे कि काश वह जंगलों में गँवारों में जा बसते और (वहीं से बैठे बैठे) तुम्हारे हालात दरयाफ्त करते रहते और अगर उनको तुम लोगों में रहना पड़ता तो फ़क़त (पीछा छुड़ाने को) ज़रा ज़हूर (कहीं) लड़ते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,21,'Al-Ahzaab','لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةࣱ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرࣰ ا','تم کو پیغمبر خدا کی پیروی (کرنی) بہتر ہے (یعنی) اس شخص کو جسے خدا (سے ملنے) اور روز قیامت (کے آنے) کی اُمید ہو اور وہ خدا کا ذکر کثرت سے کرتا ہو','Indeed, in the Messenger of Allah you have an excellent example for whoever has hope in Allah and the Last Day, and remembers Allah often','(मुसलमानों) तुम्हारे वास्ते तो खुद रसूल अल्लाह का (ख़न्दक़ में बैठना) एक अच्छा नमूना था (मगर हाँ यह) उस शख्स के वास्ते है जो खुदा और रोजे आखेरत की उम्मीद रखता हो और खुदा की याद बाकसरत करता हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,22,'Al-Ahzaab','وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُواْ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّآ إِيمَٰنࣰ ا وَتَسۡلِيمࣰ ا','اور جب مومنوں نے (کافروں کے) لشکر کو دیکھا تو کہنے لگے یہ وہی ہے جس کا خدا اور اس کے پیغمبر نے ہم سے وعدہ کیا تھا اور خدا اور اس کے پیغمبر نے سچ کہا تھا۔ اور اس سے ان کا ایمان اور اطاعت اور زیادہ ہوگئی','When the believers saw the enemy alliance, they said, “This is what Allah and His Messenger had promised us. The promise of Allah and His Messenger has come true.” And this only increased them in faith and submission','और जब सच्चे ईमानदारों ने (कुफ्फार के) जमघटों को देखा तो (बेतकल्लुफ़) कहने लगे कि ये वही चीज़ तो है जिसका हम से खुदा ने और उसके रसूल ने वायदा किया था (इसकी परवाह क्या है) और खुदा ने और उसके रसूल ने बिल्कुल ठीक कहा था और (इसके देखने से) उनका ईमानदार और उनकी इताअत और भी ज़िन्दा हो गयी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,23,'Al-Ahzaab','مِّنَ ٱلۡمُؤۡمِنِينَ رِجَالࣱ صَدَقُواْ مَا عَٰهَدُواْ ٱللَّهَ عَلَيۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن يَنتَظِرُۖ وَمَا بَدَّلُواْ تَبۡدِيلࣰ ا','مومنوں میں کتنے ہی ایسے شخص ہیں کہ جو اقرار اُنہوں نے خدا سے کیا تھا اس کو سچ کر دکھایا۔ تو ان میں بعض ایسے ہیں جو اپنی نذر سے فارغ ہوگئے اور بعض ایسے ہیں کہ انتظار کر رہے ہیں اور اُنہوں نے (اپنے قول کو) ذرا بھی نہیں بدلا','Among the believers are men who have proven true to what they pledged to Allah. Some of them have fulfilled their pledge ˹with their lives˺, others are waiting ˹their turn˺. They have never changed ˹their commitment˺ in the least','ईमानदारों में से कुछ लोग ऐसे भी हैं कि खुदा से उन्होंने (जॉनिसारी का) जो एहद किया था उसे पूरा कर दिखाया ग़रज़ उनमें से बाज़ वह हैं जो (मर कर) अपना वक्त पूरा कर गए और उनमें से बाज़ (हुक्मे खुदा के) मुन्तज़िर बैठे हैं और उन लोगों ने (अपनी बात) ज़रा भी नहीं बदली');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,24,'Al-Ahzaab','لِّيَجۡزِيَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدۡقِهِمۡ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ إِن شَآءَ أَوۡ يَتُوبَ عَلَيۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورࣰ ا رَّحِيمࣰ ا','تاکہ خدا سچّوں کو اُن کی سچائی کا بدلہ دے اور منافقوں کو چاہے تو عذاب دے اور (چاہے) تو اُن پر مہربانی کرے۔ بےشک خدا بخشنے والا مہربان ہے','˹It all happened˺ so Allah may reward the faithful for their faithfulness, and punish the hypocrites if He wills or turn to them ˹in mercy˺. Surely Allah is All-Forgiving, Most Merciful','ये इम्तेहान इसलिए था ताकि खुद सच्चे (ईमानदारों) को उनकी सच्चाई की जज़ाए ख़ैर दे और अगर चाहे तो मुनाफेक़ीन की सज़ा करे या (अगर वह लागे तौबा करें तो) खुदा उनकी तौबा कुबूल फरमाए इसमें शक नहीं कि खुदा बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,25,'Al-Ahzaab','وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُواْ بِغَيۡظِهِمۡ لَمۡ يَنَالُواْ خَيۡرࣰ اۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِينَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزࣰ ا','اور جو کافر تھے اُن کو خدا نے پھیر دیا وہ اپنے غصے میں (بھرے ہوئے تھے) کچھ بھلائی حاصل نہ کر سکے۔ اور خدا مومنوں کو لڑائی کے بارے میں کافی ہوا۔ اور خدا طاقتور (اور) زبردست ہے','And Allah drove back the disbelievers in their rage, totally empty-handed. And Allah spared the believers from fighting. For Allah is All-Powerful, Almighty','और खुदा ने (अपनी कुदरत से) क़ाफिरों को मदीने से फेर दिया (और वह लोग) अपनी झुंझलाहट में (फिर गए) और इन्हें कुछ फायदे भी न हुआ और खुदा ने (अपनी मेहरबानी से) मोमिनीन को लड़ने की नौबत न आने दी और खुदा तो (बड़ा) ज़बरदस्त (और) ग़ालिब हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,26,'Al-Ahzaab','وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن صَيَاصِيهِمۡ وَقَذَفَ فِي قُلُوبِهِمُ ٱلرُّعۡبَ فَرِيقࣰ ا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِيقࣰ ا','اور اہل کتاب میں سے جنہوں نے اُن کی مدد کی تھی اُن کو اُن کے قلعوں سے اُتار دیا اور اُن کے دلوں میں دہشت ڈال دی۔ تو کتنوں کو تم قتل کر دیتے تھے اور کتنوں کو قید کرلیتے تھے','And He brought down those from the People of the Book who supported the enemy alliance from their own strongholds, and cast horror into their hearts. You ˹believers˺ killed some, and took others captive','और अहले किताब में से जिन लोगों (बनी कुरैज़ा) ने उन (कुफ्फार) की मदद की थी खुदा उनको उनके क़िलों से (बेदख़ल करके) नीचे उतार लाया और उनके दिलों में (तुम्हारा) ऐसा रोब बैठा दिया कि तुम उनके कुछ लोगों को क़त्ल करने लगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,27,'Al-Ahzaab','وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِيَٰرَهُمۡ وَأَمۡوَٰلَهُمۡ وَأَرۡضࣰ ا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣰ ا','اور اُن کی زمین اور ان کے گھروں اور ان کے مال کا اور اس زمین کا جس میں تم نے پاؤں بھی نہیں رکھا تھا تم کو وارث بنا دیا۔ اور خدا ہر چیز پر قدرت رکھتا ہے','He has also caused you to take over their lands, homes, and wealth, as well as lands you have not yet set foot on. And Allah is Most Capable of everything','और कुछ को क़ैदी (और गुलाम) बनाने और तुम ही लोगों को उनकी ज़मीन और उनके घर और उनके माल और उस ज़मीन (खैबर) का खुदा ने मालिक बना दिया जिसमें तुमने क़दम तक नहीं रखा था और खुदा तो हर चीज़ पर क़ादिर वतवाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,28,'Al-Ahzaab','يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّأَزۡوَٰجِكَ إِن كُنتُنَّ تُرِدۡنَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا فَتَعَالَيۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ سَرَاحࣰ ا جَمِيلࣰ ا','اے پیغمبر اپنی بیویوں سے کہہ دو کہ اگر تم دنیا کی زندگی اور اس کی زینت وآرائش کی خواستگار ہو تو آؤ میں تمہیں کچھ مال دوں اور اچھی طرح سے رخصت کردوں','O Prophet! Say to your wives, “If you desire the life of this world and its luxury, then come, I will give you a ˹suitable˺ compensation ˹for divorce˺ and let you go graciously','ऐ रसूल अपनी बीवियों से कह दो कि अगर तुम (फक़त) दुनियावी ज़िन्दगी और उसकी आराइश व ज़ीनत की ख्वाहॉ हो तो उधर आओ मैं तुम लोगों को कुछ साज़ो सामान दे दूँ और उनवाने शाइस्ता से रूख़सत कर दूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,29,'Al-Ahzaab','وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡأٓخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَٰتِ مِنكُنَّ أَجۡرًا عَظِيمࣰ ا','اور اگر تم خدا اور اس کے پیغمبر اور عاقبت کے گھر (یعنی بہشت) کی طلبگار ہو تو تم میں جو نیکوکاری کرنے والی ہیں اُن کے لئے خدا نے اجر عظیم تیار کر رکھا ہے','But if you desire Allah and His Messenger and the ˹everlasting˺ Home of the Hereafter, then Surely Allah has prepared a great reward for those of you who do good.”','और अगर तुम लोग खुदा और उसके रसूल और आखेरत के घर की ख्वाहॉ हो तो (अच्छी तरह ख्याल रखो कि) तुम लोगों में से नेकोकार औरतों के लिए खुदा ने यक़ीनन् बड़ा (बड़ा) अज्र व (सवाब) मुहय्या कर रखा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,30,'Al-Ahzaab','يَٰنِسَآءَ ٱلنَّبِيِّ مَن يَأۡتِ مِنكُنَّ بِفَٰحِشَةࣲ مُّبَيِّنَةࣲ يُضَٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَيۡنِۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣰ ا','اے پیغمبر کی بیویو تم میں سے جو کوئی صریح ناشائستہ (الفاظ کہہ کر رسول الله کو ایذا دینے کی) حرکت کرے گی۔ اس کو دونی سزا دی جائے گی۔ اور یہ (بات) خدا کو آسان ہے','O wives of the Prophet! If any of you were to commit a blatant misconduct, the punishment would be doubled for her. And that is easy for Allah','ऐ पैग़म्बर की बीबियों तुममें से जो कोई किसी सरीही ना शाइस्ता हरकत की का मुरतिब हुई तो (याद रहे कि) उसका अज़ाब भी दुगना बढ़ा दिया जाएगा और खुदा के वास्ते (निहायत) आसान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,31,'Al-Ahzaab','۞وَمَن يَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَٰلِحࣰ ا نُّؤۡتِهَآ أَجۡرَهَا مَرَّتَيۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقࣰ ا كَرِيمࣰ ا','اور جو تم میں سے خدا اور اس کے رسول کی فرمانبردار رہے گی اور عمل نیک کرے گی۔ اس کو ہم دونا ثواب دیں گے اور اس کے لئے ہم نے عزت کی روزی تیار کر رکھی ہے','And whoever of you devoutly obeys Allah and His Messenger and does good, We will grant her double the reward, and We have prepared for her an honourable provision','और तुममें से जो (बीवी) खुदा और उसके रसूल की ताबेदारी अच्छे (अच्छे) काम करेगी उसको हम उसका सवाब भी दोहरा अता करेगें और हमने उसके लिए (जन्नत में) इज्ज़त की रोज़ी तैयार कर रखी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,32,'Al-Ahzaab','يَٰنِسَآءَ ٱلنَّبِيِّ لَسۡتُنَّ كَأَحَدࣲ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيۡتُنَّۚ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَيَطۡمَعَ ٱلَّذِي فِي قَلۡبِهِۦ مَرَضࣱ وَقُلۡنَ قَوۡلࣰ ا مَّعۡرُوفࣰ ا','اے پیغمبر کی بیویو تم اور عورتوں کی طرح نہیں ہو۔ اگر تم پرہیزگار رہنا چاہتی ہو تو کسی (اجنبی شخص سے) نرم نرم باتیں نہ کیا کرو تاکہ وہ شخص جس کے دل میں کسی طرح کا مرض ہے کوئی امید (نہ) پیدا کرے۔ اور ان دستور کے مطابق بات کیا کرو','O wives of the Prophet! You are not like any other women: if you are mindful ˹of Allah˺, then do not be overly effeminate in speech ˹with men˺ or those with sickness in their hearts may be tempted, but speak in a moderate tone','ऐ नबी की बीवियों तुम और मामूली औरतों की सी तो हो वही (बस) अगर तुम को परहेज़गारी मंजूर रहे तो (अजनबी आदमी से) बात करने में नरम नरम (लगी लिपटी) बात न करो ताकि जिसके दिल में (शहवते ज़िना का) मर्ज़ है वह (कुछ और) इरादा (न) करे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,33,'Al-Ahzaab','وَقَرۡنَ فِي بُيُوتِكُنَّ وَلَا تَبَرَّجۡنَ تَبَرُّجَ ٱلۡجَٰهِلِيَّةِ ٱلۡأُولَىٰۖ وَأَقِمۡنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعۡنَ ٱللَّهَ وَرَسُولَهُۥٓۚ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ تَطۡهِيرࣰ ا','اور اپنے گھروں میں ٹھہری رہو اور جس طرح (پہلے) جاہلیت (کے دنوں) میں اظہار تجمل کرتی تھیں اس طرح زینت نہ دکھاؤ۔ اور نماز پڑھتی رہو اور زکوٰة دیتی رہو اور خدا اور اس کے رسول کی فرمانبرداری کرتی رہو۔ اے (پیغمبر کے) اہل بیت خدا چاہتا ہے کہ تم سے ناپاکی (کا میل کچیل) دور کردے اور تمہیں بالکل پاک صاف کردے','Settle in your homes, and do not display yourselves as women did in the days of ˹pre-Islamic˺ ignorance. Establish prayer, pay alms-tax, and obey Allah and His Messenger. Allah only intends to keep ˹the causes of˺ evil away from you and purify you completely, O members of the ˹Prophet’s˺ family','और (साफ-साफ) उनवाने शाइस्ता से बात किया करो और अपने घरों में निचली बैठी रहो और अगले ज़माने जाहिलियत की तरह अपना बनाव सिंगार न दिखाती फिरो और पाबन्दी से नमाज़ पढ़ा करो और (बराबर) ज़कात दिया करो और खुदा और उसके रसूल की इताअत करो ऐ (पैग़म्बर के) अहले बैत खुदा तो बस ये चाहता है कि तुमको (हर तरह की) बुराई से दूर रखे और जो पाक व पाकीज़ा दिखने का हक़ है वैसा पाक व पाकीज़ा रखे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,34,'Al-Ahzaab','وَٱذۡكُرۡنَ مَا يُتۡلَىٰ فِي بُيُوتِكُنَّ مِنۡ ءَايَٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا','اور تمہارے گھروں میں جو خدا کی آیتیں پڑھی جاتی ہیں اور حکمت (کی باتیں سنائی جاتی ہیں) ان کو یاد رکھو۔ بےشک خدا باریک بیں اور باخبر ہے','˹Always˺ remember what is recited in your homes of Allah’s revelations and ˹prophetic˺ wisdom. Surely Allah is Most Subtle, All-Aware','और (ऐ नबी की बीबियों) तुम्हारे घरों में जो खुदा की आयतें और (अक़ल व हिकमत की बातें) पढ़ी जाती हैं उनको याद रखो कि बेशक ख़ुदा बड़ा बारीक है वाक़िफकार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,35,'Al-Ahzaab','إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ وَٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ وَٱلۡقَٰنِتِينَ وَٱلۡقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلۡخَٰشِعِينَ وَٱلۡخَٰشِعَٰتِ وَٱلۡمُتَصَدِّقِينَ وَٱلۡمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرࣰ ا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةࣰ وَأَجۡرًا عَظِيمࣰ ا','(جو لوگ خدا کے آگے سر اطاعت خم کرنے والے ہیں یعنی) مسلمان مرد اور مسلمان عورتیں اور مومن مرد اور مومن عورتیں اور فرماں بردار مرد اور فرماں بردار عورتیں اور راست باز مرد اور راست باز عورتیں اور صبر کرنے والے مرد اور صبر کرنے والی عورتیں اور فروتنی کرنے والے مرد اور فروتنی کرنے والی عورتیں اور خیرات کرنے والے مرد اور اور خیرات کرنے والی عورتیں اور روزے رکھنے والے مرد اور روزے رکھنے والی عورتیں اور اپنی شرمگاہوں کی حفاظت کرنے والے مرد اور حفاظت کرنے والی عورتیں اور خدا کو کثرت سے یاد کرنے والے مرد اور کثرت سے یاد کرنے والی عورتیں۔ کچھ شک نہیں کہ ان کے لئے خدا نے بخشش اور اجر عظیم تیار کر رکھا ہے','Surely ˹for˺ Muslim men and women, believing men and women, devout men and women, truthful men and women, patient men and women, humble men and women, charitable men and women, fasting men and women, men and women who guard their chastity, and men and women who remember Allah often—for ˹all of˺ them Allah has prepared forgiveness and a great reward','(दिल लगा के सुनो) मुसलमान मर्द और मुसलमान औरतें और ईमानदार मर्द और ईमानदार औरतें और फरमाबरदार मर्द और फरमाबरदार औरतें और रास्तबाज़ मर्द और रास्तबाज़ औरतें और सब्र करने वाले मर्द और सब्र करने वाली औरतें और फिरौतनी करने वाले मर्द और फिरौतनी करने वाली औरतें और Âैरात करने वाले मर्द और Âैरात करने वाली औरतें और रोज़ादार मर्द और रोज़ादार औरतें और अपनी शर्मगाहों की हिफाज़त करने वाले मर्द और हिफाज़त करने वाली औरतें और खुदा की बकसरत याद करने वाले मर्द और याद करने वाली औरतें बेशक इन सब लोगों के वास्ते खुदा ने मग़फिरत और (बड़ा) सवाब मुहैय्या कर रखा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,36,'Al-Ahzaab','وَمَا كَانَ لِمُؤۡمِنࣲ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمۡرًا أَن يَكُونَ لَهُمُ ٱلۡخِيَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَٰلࣰ ا مُّبِينࣰ ا','اور کسی مومن مرد اور مومن عورت کو حق نہیں ہے کہ جب خدا اور اس کا رسول کوئی امر مقرر کردیں تو وہ اس کام میں اپنا بھی کچھ اختیار سمجھیں۔ اور جو کوئی خدا اور اس کے رسول کی نافرمانی کرے وہ صریح گمراہ ہوگیا','It is not for a believing man or woman—when Allah and His Messenger decree a matter—to have any other choice in that matter. Indeed, whoever disobeys Allah and His Messenger has clearly gone ˹far˺ astray','और न किसी ईमानदार मर्द को ये मुनासिब है और न किसी ईमानदार औरत को जब खुदा और उसके रसूल किसी काम का हुक्म दें तो उनको अपने उस काम (के करने न करने) अख़तेयार हो और (याद रहे कि) जिस शख्स ने खुदा और उसके रसूल की नाफरमानी की वह यक़ीनन खुल्लम खुल्ला गुमराही में मुब्तिला हो चुका');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,37,'Al-Ahzaab','وَإِذۡ تَقُولُ لِلَّذِيٓ أَنۡعَمَ ٱللَّهُ عَلَيۡهِ وَأَنۡعَمۡتَ عَلَيۡهِ أَمۡسِكۡ عَلَيۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِي فِي نَفۡسِكَ مَا ٱللَّهُ مُبۡدِيهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَيۡدࣱ مِّنۡهَا وَطَرࣰ ا زَوَّجۡنَٰكَهَا لِكَيۡ لَا يَكُونَ عَلَى ٱلۡمُؤۡمِنِينَ حَرَجࣱ فِيٓ أَزۡوَٰجِ أَدۡعِيَآئِهِمۡ إِذَا قَضَوۡاْ مِنۡهُنَّ وَطَرࣰ اۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولࣰ ا','اور جب تم اس شخص سے جس پر خدا نے احسان کیا اور تم نے بھی احسان کیا (یہ) کہتے تھے کہ اپنی بیوی کو اپنے پاس رہنے دے اور خدا سے ڈر اور تم اپنے دل میں وہ بات پوشیدہ کرتے تھے جس کو خدا ظاہر کرنے والا تھا اور تم لوگوں سے ڈرتے تھے۔ حالانکہ خدا ہی اس کا زیادہ مستحق ہے کہ اس سے ڈرو۔ پھر جب زید نے اس سے (کوئی) حاجت (متعلق) نہ رکھی (یعنی اس کو طلاق دے دی) تو ہم نے تم سے اس کا نکاح کردیا تاکہ مومنوں کے لئے ان کے منہ بولے بیٹوں کی بیویوں (کے ساتھ نکاح کرنے کے بارے) میں جب وہ ان سے اپنی حاجت (متعلق) نہ رکھیں (یعنی طلاق دے دیں) کچھ تنگی نہ رہے۔ اور خدا کا حکم واقع ہو کر رہنے والا تھا','And ˹remember, O Prophet,˺ when you said to the one for whom Allah has done a favour and you ˹too˺ have done a favour, “Keep your wife and fear Allah,” while concealing within yourself what Allah was going to reveal. And ˹so˺ you were considering the people, whereas Allah was more worthy of your consideration. So when Zaid totally lost interest in ˹keeping˺ his wife, We gave her to you in marriage, so that there would be no blame on the believers for marrying the ex-wives of their adopted sons after their divorce. And Allah’s command is totally binding','और (ऐ रसूल वह वक्त याद करो) जब तुम उस शख्स (ज़ैद) से कह रहे थे जिस पर खुदा ने एहसान (अलग) किया था और तुमने उस पर (अलग) एहसान किया था कि अपनी बीबी (ज़ैनब) को अपनी ज़ौज़ियत में रहने दे और खुदा से डेर खुद तुम इस बात को अपने दिल में छिपाते थे जिसको (आख़िरकार) खुदा ज़ाहिर करने वाला था और तुम लोगों से डरते थे हालॉकि खुदा इसका ज्यादा हक़दार है कि तुम उस से डरो ग़रज़ जब ज़ैद अपनी हाजत पूरी कर चुका (तलाक़ दे दी) तो हमने (हुक्म देकर) उस औरत (ज़ैनब) का निकाह तुमसे कर दिया ताकि आम मोमिनीन को अपने ले पालक लड़कों की बीवियों (से निकाह करने) में जब वह अपना मतलब उन औरतों से पूरा कर चुकें (तलाक़ दे दें) किसी तरह की तंगी न रहे और खुदा का हुक्म तो किया कराया हुआ (क़तई) होता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,38,'Al-Ahzaab','مَّا كَانَ عَلَى ٱلنَّبِيِّ مِنۡ حَرَجࣲ فِيمَا فَرَضَ ٱللَّهُ لَهُۥۖ سُنَّةَ ٱللَّهِ فِي ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلُۚ وَكَانَ أَمۡرُ ٱللَّهِ قَدَرࣰ ا مَّقۡدُورًا','پیغمبر پر اس کام میں کچھ تنگی نہیں جو خدا نے ان کے لئے مقرر کردیا۔ اور جو لوگ پہلے گزر چکے ہیں ان میں بھی خدا کا یہی دستور رہا ہے۔ اور خدا کا حکم ٹھیر چکا ہے','There is no blame on the Prophet for doing what Allah has ordained for him. That has been the way of Allah with those ˹prophets˺ who had gone before. And Allah’s command has been firmly decreed','जो हुक्म खुदा ने पैग़म्बर पर फर्ज क़र दिया (उसके करने) में उस पर कोई मुज़ाएका नहीं जो लोग (उनसे) पहले गुज़र चुके हैं उनके बारे में भी खुदा का (यही) दस्तूर (जारी) रहा है (कि निकाह में तंगी न की) और खुदा का हुक्म तो (ठीक अन्दाज़े से) मुक़र्रर हुआ होता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,39,'Al-Ahzaab','ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخۡشَوۡنَهُۥ وَلَا يَخۡشَوۡنَ أَحَدًا إِلَّا ٱللَّهَۗ وَكَفَىٰ بِٱللَّهِ حَسِيبࣰ ا','اور جو خدا کے پیغام (جوں کے توں) پہنچاتے اور اس سے ڈرتے ہیں اور خدا کے سوا کسی سے نہیں ڈرتے تھے۔ اور خدا ہی حساب کرنے کو کافی ہے','˹That is His way with˺ those ˹prophets˺ who deliver the messages of Allah, and consider Him, and none but Allah. And sufficient is Allah as a ˹vigilant˺ Reckoner','वह लोग जो खुदा के पैग़ामों को (लोगों तक जूँ का तूँ) पहुँचाते थे और उससे डरते थे और खुदा के सिवा किसी से नहीं डरते थे (फिर तुम क्यों डरते हो) और हिसाब लेने के वास्ते तो खुद काफ़ी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,40,'Al-Ahzaab','مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدࣲ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمࣰ ا','محمدﷺ تمہارے مردوں میں سے کسی کے والد نہیں ہیں بلکہ خدا کے پیغمبر اور نبیوں (کی نبوت) کی مہر (یعنی اس کو ختم کردینے والے) ہیں اور خدا ہر چیز سے واقف ہے','Muḥammad is not the father of any of your men, but is the Messenger of Allah and the seal of the prophets. And Allah has ˹perfect˺ knowledge of all things','(लोगों) मोहम्मद तुम्हारे मर्दों में से (हक़ीक़तन) किसी के बाप नहीं हैं (फिर जैद की बीवी क्यों हराम होने लगी) बल्कि अल्लाह के रसूल और नबियों की मोहर (यानी ख़त्म करने वाले) हैं और खुदा तो हर चीज़ से खूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,41,'Al-Ahzaab','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱذۡكُرُواْ ٱللَّهَ ذِكۡرࣰ ا كَثِيرࣰ ا','اے اہل ایمان خدا کا بہت ذکر کیا کرو','O believers! Always remember Allah often','ऐ ईमानवालों बाकसरत खुदा की याद किया करो और');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,42,'Al-Ahzaab','وَسَبِّحُوهُ بُكۡرَةࣰ وَأَصِيلًا','اور صبح اور شام اس کی پاکی بیان کرتے رہو','and glorify Him morning and evening','सुबह व शाम उसकी तसबीह करते रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,43,'Al-Ahzaab','هُوَ ٱلَّذِي يُصَلِّي عَلَيۡكُمۡ وَمَلَٰٓئِكَتُهُۥ لِيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِينَ رَحِيمࣰ ا','وہی تو ہے جو تم پر رحمت بھیجتا ہے اور اس کے فرشتے بھی۔ تاکہ تم کو اندھیروں سے نکال کر روشنی کی طرف لے جائے۔ اور خدا مومنوں پر مہربان ہے','He is the One Who showers His blessings upon you—and His angels pray for you—so that He may bring you out of darkness and into light. For He is ever Merciful to the believers','वह वही तो है जो खुद तुमपर दूरूद (दर्दों रहमत) भेजता है और उसके फ़रिश्ते ताकि तुमको (कुफ़्र की) तारीक़ियों से निकालकर (ईमान की) रौशनी में ले जाए और खुदा ईमानवालों पर बड़ा मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,44,'Al-Ahzaab','تَحِيَّتُهُمۡ يَوۡمَ يَلۡقَوۡنَهُۥ سَلَٰمࣱۚ وَأَعَدَّ لَهُمۡ أَجۡرࣰ ا كَرِيمࣰ ا','جس روز وہ اس سے ملیں گے ان کا تحفہ (خدا کی طرف سے) سلام ہوگا اور اس نے ان کے لئے بڑا ثواب تیار کر رکھا ہے','Their greeting on the Day they meet Him will be, “Peace!” And He has prepared for them an honourable reward','जिस दिन उसकी बारगाह में हाज़िर होंगे (उस दिन) उनकी मुरादात (उसकी तरफ से हर क़िस्म की) सलामती होगी और खुदा ने तो उनके वास्ते बहुत अच्छा बदला (बेहश्त) तैयार रखा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,45,'Al-Ahzaab','يَٰٓأَيُّهَا ٱلنَّبِيُّ إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدࣰ ا وَمُبَشِّرࣰ ا وَنَذِيرࣰ ا','اے پیغمبر ہم نے تم کو گواہی دینے والا اور خوشخبری سنانے اور ڈرانے والا بنا کر بھیجا ہے','O Prophet! We have sent you as a witness, and a deliverer of good news, and a warner','ऐ नबी हमने तुमको (लोगों का) गवाह और (नेकों को बेहश्त की) खुशख़बरी देने वाला और बदों को अज़ाब से डराने वाला');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,46,'Al-Ahzaab','وَدَاعِيًا إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجࣰ ا مُّنِيرࣰ ا','اور خدا کی طرف بلانے والا اور چراغ روشن','and a caller to ˹the Way of˺ Allah by His command, and a beacon of light','और खुदा की तरफ उसी के हुक्म से बुलाने वाला और (ईमान व हिदायत का) रौशन चिराग़ बनाकर भेजा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,47,'Al-Ahzaab','وَبَشِّرِ ٱلۡمُؤۡمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضۡلࣰ ا كَبِيرࣰ ا','اور مومنوں کو خوشخبری سنا دو کہ ان کے لئے خدا کی طرف سے بڑا فضل ہوگا','Give good news to the believers that they will have a great bounty from Allah','और तुम मोमिनीन को खुशख़बरी दे दो कि उनके लिए खुदा की तरफ से बहुत बड़ी (मेहरबानी और) बख्शिश है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (33,48,'Al-Ahzaab','وَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَٱلۡمُنَٰفِقِينَ وَدَعۡ أَذَىٰهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلࣰ ا','اور کافروں اور منافقوں کا کہا نہ ماننا اور نہ ان کے تکلیف دینے پر نظر کرنا اور خدا پر بھروسہ رکھنا۔ اور خدا ہی کارساز کافی ہے','Do not yield to the disbelievers and the hypocrites. Overlook their annoyances, and put your trust in Allah. For Allah is sufficient as a Trustee of Affairs','और (ऐ रसूल) तुम (कहीं) काफिरों और मुनाफिक़ों की इताअत न करना और उनकी ईज़ारसानी का ख्याल छोड़ दो और खुदा पर भरोसा रखो और कारसाज़ी में खुदा काफ़ी है');
